values
  ('7ccc3537-d317-4dc5-bb86-8896b5f3b540', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', null, 'topic'::public.curated_course_node_type, 'Hospitality Digital Ecosystem and Systems Thinking', 'Hospitality technology is a connected service system, not a collection of isolated applications. This section gives students a managerial map of how people, processes, data, devices, vendors, and platforms combine to deliver the guest experience and business performance.', 0),
  ('b4274d5b-e2a3-44f5-84d9-fa1fd3d6ac36', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '7ccc3537-d317-4dc5-bb86-8896b5f3b540', 'subtopic'::public.curated_course_node_type, 'Enterprise and property technology landscape', 'Students learn the major layers of a hotel, resort, restaurant, and multi-property technology stack so they can locate a problem before proposing a tool.', 0),
  ('3c9b83a5-1fd4-41c1-bb1f-4e6711f477ef', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'b4274d5b-e2a3-44f5-84d9-fa1fd3d6ac36', 'concept'::public.curated_course_node_type, 'Guest-facing, operational, commercial, financial, workforce, facilities, and enterprise systems', null, 0),
  ('07f286f2-c4c2-452e-933f-2168fba1b4e2', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'b4274d5b-e2a3-44f5-84d9-fa1fd3d6ac36', 'concept'::public.curated_course_node_type, 'Property, cluster, brand, owner, franchise, management-company, and third-party perspectives', null, 1),
  ('cdb84a67-4950-4428-b610-c49dec3aa058', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'b4274d5b-e2a3-44f5-84d9-fa1fd3d6ac36', 'concept'::public.curated_course_node_type, 'Cloud, on-premises, edge, mobile, software-as-a-service, and platform models', null, 2),
  ('0392e43a-3a93-457d-b9b8-927f2000876f', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '7ccc3537-d317-4dc5-bb86-8896b5f3b540', 'subtopic'::public.curated_course_node_type, 'Systems thinking and service processes', 'This subtopic connects technology choices to the end-to-end work that creates value for guests and employees.', 1),
