  ('8eea02ff-455f-4905-9d33-2d0bc42dd613', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '7d8b4eb9-e616-4180-a721-32f92b8ddc21', 'concept'::public.curated_course_node_type, 'Total cost of ownership, opportunity cost, benefits realization, and technical debt', null, 2),
  ('7359a7fe-7339-43ac-b2d7-be24bd43f73d', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', null, 'topic'::public.curated_course_node_type, 'Property Management Systems and Lodging Operations', 'The property management system is the operational hub of lodging. Students learn the guest-account and room-inventory logic behind the screens so they can design controls, diagnose exceptions, and improve service.', 1),
  ('072bd533-baa7-4a6c-943c-11ca07bb87dd', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '7359a7fe-7339-43ac-b2d7-be24bd43f73d', 'subtopic'::public.curated_course_node_type, 'Reservation-to-departure workflow', 'Students trace the guest record and stay through its full life cycle, including the exceptions that expose weak processes.', 0),
