  ('eac885e4-8516-46ca-b02d-28b8336e75dc', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '072bd533-baa7-4a6c-943c-11ca07bb87dd', 'concept'::public.curated_course_node_type, 'Pre-arrival, registration, room assignment, keys, check-in, stay changes, and check-out', null, 1),
  ('f91792d7-8554-47ce-96c5-8e5ece89b9ad', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '072bd533-baa7-4a6c-943c-11ca07bb87dd', 'concept'::public.curated_course_node_type, 'Walks, overbooking, room moves, split stays, extensions, early departures, and service recovery', null, 2),
  ('ab2d6d58-10bd-408f-8fee-af8e41b24522', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '7359a7fe-7339-43ac-b2d7-be24bd43f73d', 'subtopic'::public.curated_course_node_type, 'Rooms, rates, folios, and night audit', 'This subtopic explains the operational data structures that support inventory control, posting, settlement, and daily close.', 1),
  ('b68f26b1-8f6d-45b2-90c7-cd98eaae3ba3', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'ab2d6d58-10bd-408f-8fee-af8e41b24522', 'concept'::public.curated_course_node_type, 'Room types, room status, housekeeping, out-of-order, and maintenance coordination', null, 0),
  ('d826a910-cb3a-4728-bd5e-864417848432', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'ab2d6d58-10bd-408f-8fee-af8e41b24522', 'concept'::public.curated_course_node_type, 'Rate plans, packages, restrictions, routing, allowances, taxes, fees, and folio windows', null, 1),
