  ('f116aa41-2747-4d76-9871-1a5fd20887fd', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'd39585db-9a2d-4ed8-b515-fd2a1c3025cb', 'concept'::public.curated_course_node_type, 'Profiles, negotiated rates, group blocks, allotments, and central services', null, 1),
  ('e2e3cdc9-7cc6-442e-aa17-96dd4fbdd7e0', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'd39585db-9a2d-4ed8-b515-fd2a1c3025cb', 'concept'::public.curated_course_node_type, 'Standard operating procedures, data ownership, support tiers, and property-level autonomy', null, 2),
  ('fb17a2e3-4c39-4216-9077-073c2e9f4284', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', null, 'topic'::public.curated_course_node_type, 'Point-of-Sale, Foodservice, Inventory, and Procurement Systems', 'Food-and-beverage systems join guest service with production, inventory, labor, payments, and accounting. This section prepares students to evaluate both front-of-house speed and back-of-house control.', 2),
  ('cfbd1139-fa59-4797-975b-6a4d855e02e9', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'fb17a2e3-4c39-4216-9077-073c2e9f4284', 'subtopic'::public.curated_course_node_type, 'POS transaction and service design', 'Students connect menu design and service style to ordering, routing, fulfillment, payment, and recovery workflows.', 0),
