  ('1d3a59bf-11f2-4710-ad95-b568902a70c5', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '5dc9966e-7679-46b5-b5fc-bbb8729d3dec', 'concept'::public.curated_course_node_type, 'Revenue centers, tenders, taxes, tips, charge-to-room, and general-ledger mapping', null, 2),
