  ('59885c21-9fd3-4e80-b4b0-3acfa48a75e1', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '291fdb66-5d2f-496d-ae70-dbfe03ffb0c7', 'subtopic'::public.curated_course_node_type, 'Responsible personalization', 'Students design relevant offers and service prompts while respecting choice, fairness, dignity, and context.', 2),
  ('40ed6ddf-66e8-412f-a89d-7de2c9fa6e3d', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '59885c21-9fd3-4e80-b4b0-3acfa48a75e1', 'concept'::public.curated_course_node_type, 'Next-best action, recommendations, preference fulfillment, and human override', null, 0),
  ('bff67d89-32b7-4a99-894f-6531e95e8496', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '59885c21-9fd3-4e80-b4b0-3acfa48a75e1', 'concept'::public.curated_course_node_type, 'Consent, transparency, data minimization, purpose limitation, and sensitive attributes', null, 1),
  ('a69b23e9-a0db-41af-90a8-61bc0dbcce08', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '59885c21-9fd3-4e80-b4b0-3acfa48a75e1', 'concept'::public.curated_course_node_type, 'Bias testing, exclusion, vulnerable guests, accessibility, complaint handling, and opt-out', null, 2),
  ('d11312ca-323c-48f3-aa11-aebd8d2c0da7', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', null, 'topic'::public.curated_course_node_type, 'Revenue Management Systems and Commercial Decision Support', 'Revenue systems turn demand signals, capacity, price, and controls into commercial recommendations. Students learn both the analytical logic and the managerial responsibility to challenge outputs.', 5),
  ('90b6ed11-5921-4062-b929-3b7c1214adba', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'd11312ca-323c-48f3-aa11-aebd8d2c0da7', 'subtopic'::public.curated_course_node_type, 'Forecasting and demand signals', 'Students examine how systems estimate unconstrained demand and uncertainty from internal and external evidence.', 0),
  ('86c50f45-4698-4f0d-b02f-cf009528d6b0', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '90b6ed11-5921-4062-b929-3b7c1214adba', 'concept'::public.curated_course_node_type, 'Bookings, pace, pickup, cancellations, no-shows, length of stay, and lead time', null, 0),
  ('eff7f3f6-7a49-4d92-8cff-65860acab94e', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '90b6ed11-5921-4062-b929-3b7c1214adba', 'concept'::public.curated_course_node_type, 'Events, holidays, competitors, search, web traffic, weather, and market intelligence', null, 1),
  ('a3795385-ce0f-4180-bf66-b975fff4e14c', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '90b6ed11-5921-4062-b929-3b7c1214adba', 'concept'::public.curated_course_node_type, 'Forecast horizon, granularity, seasonality, outliers, scenario ranges, and forecast error', null, 2),
  ('c65a7bdc-19c7-4d48-a9ef-edcc2cca2833', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'd11312ca-323c-48f3-aa11-aebd8d2c0da7', 'subtopic'::public.curated_course_node_type, 'Optimization, pricing, and inventory controls', 'This subtopic explains how RMS recommendations influence price, availability, and acceptance decisions.', 1),
  ('649c23fc-384b-4f48-9f5b-f63e35013ba5', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'c65a7bdc-19c7-4d48-a9ef-edcc2cca2833', 'concept'::public.curated_course_node_type, 'Segments, willingness to pay, price sensitivity, rate fences, and dynamic pricing', null, 0),
  ('518a972e-9bd4-47fe-aaad-9ecd8ea9682a', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'c65a7bdc-19c7-4d48-a9ef-edcc2cca2833', 'concept'::public.curated_course_node_type, 'Overbooking, minimum stay, closed-to-arrival, nested inventory, and displacement', null, 1),
  ('3c5b1528-208a-4a57-ae13-8e41683bca0d', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'c65a7bdc-19c7-4d48-a9ef-edcc2cca2833', 'concept'::public.curated_course_node_type, 'Group evaluation, bid price, upgrades, ancillary revenue, and total revenue management', null, 2),
  ('df09010e-00e3-4874-861e-4f14f9e5088d', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'd11312ca-323c-48f3-aa11-aebd8d2c0da7', 'subtopic'::public.curated_course_node_type, 'Governance and performance', 'Students learn to monitor model outputs and commercial outcomes rather than treating automation as unquestionable authority.', 2),
  ('2abd8c96-8338-4f54-ac77-d48fa1a1ed3d', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'df09010e-00e3-4874-861e-4f14f9e5088d', 'concept'::public.curated_course_node_type, 'ADR, occupancy, RevPAR, TRevPAR, GOPPAR, contribution, and channel cost', null, 0),
  ('7c954d21-9ccf-4103-b635-7e5905b54461', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'df09010e-00e3-4874-861e-4f14f9e5088d', 'concept'::public.curated_course_node_type, 'Overrides, reason codes, alerts, thresholds, approval rights, and revenue meetings', null, 1),
  ('036ddb31-a016-4344-b1a7-1379d4fc760b', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'df09010e-00e3-4874-861e-4f14f9e5088d', 'concept'::public.curated_course_node_type, 'Model drift, feedback loops, price fairness, collusion risk, explainability, and human accountability', null, 2),
  ('6afa374e-142c-4d24-9570-9e54debf3ce3', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', null, 'topic'::public.curated_course_node_type, 'Data Architecture, Integration, APIs, and Interoperability', 'Reliable hospitality operations depend on systems exchanging consistent data at the right time. This section gives managers enough technical fluency to specify integrations, recognize failure modes, and ask better questions.', 6),
  ('2a329080-22a7-4f68-bcb5-0983ab852830', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '6afa374e-142c-4d24-9570-9e54debf3ce3', 'subtopic'::public.curated_course_node_type, 'Data models and master data', 'Students learn why shared definitions and identifiers are prerequisites for trustworthy transactions and analytics.', 0);
