  ('2d57d500-36be-4870-9fd8-04cd03be2540', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '838c702e-af8b-4277-8b09-a8cd5be6b22d', 'concept'::public.curated_course_node_type, 'Requests, responses, authentication, schemas, mappings, validation, retries, and idempotency', null, 1),
  ('2c5645a9-6827-4604-9194-ae2cf84f2d28', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '838c702e-af8b-4277-8b09-a8cd5be6b22d', 'concept'::public.curated_course_node_type, 'Point-to-point, middleware, integration platforms, microservices, and vendor marketplaces', null, 2),
  ('760427d8-5db4-4bbc-ad38-c088487f7de4', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '6afa374e-142c-4d24-9570-9e54debf3ce3', 'subtopic'::public.curated_course_node_type, 'Interoperability and operational resilience', 'Students test integrations as business processes, including exceptions and recovery—not merely as successful message transfers.', 2),
  ('0ef63b22-8787-4b39-9dbf-589b7fe1c5c1', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '760427d8-5db4-4bbc-ad38-c088487f7de4', 'concept'::public.curated_course_node_type, 'Hospitality standards and shared schemas from HTNG and OpenTravel communities', null, 0),
  ('9bd5af0a-ee6f-4a8b-b04d-16601e15aa3c', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '760427d8-5db4-4bbc-ad38-c088487f7de4', 'concept'::public.curated_course_node_type, 'Latency, duplication, ordering, partial failure, reconciliation, observability, and audit logs', null, 1),
  ('04682a5c-c000-4389-83bb-99f5edda6956', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '760427d8-5db4-4bbc-ad38-c088487f7de4', 'concept'::public.curated_course_node_type, 'Sandbox, test cases, cutover, rollback, offline procedures, service levels, and support ownership', null, 2),
  ('d8cbe598-154e-448f-9d23-796618c1b3a5', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', null, 'topic'::public.curated_course_node_type, 'Analytics, Business Intelligence, Experimentation, and AI', 'Hospitality data becomes valuable only when it improves a decision. Students learn to frame questions, build defensible metrics, interpret evidence, and use automation with appropriate skepticism.', 7),
  ('49643b59-47cf-47ae-a49e-dd84493dc373', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'd8cbe598-154e-448f-9d23-796618c1b3a5', 'subtopic'::public.curated_course_node_type, 'Metrics and semantic consistency', 'Students define performance measures so teams do not make decisions from conflicting versions of the truth.', 0),
  ('6e5d6652-1e90-4420-8795-122a39b45cd1', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '49643b59-47cf-47ae-a49e-dd84493dc373', 'concept'::public.curated_course_node_type, 'Operational, guest, commercial, financial, workforce, sustainability, and risk measures', null, 0),
  ('7aa7f76a-bbe3-4de1-8ba6-6c7e0f5407fc', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '49643b59-47cf-47ae-a49e-dd84493dc373', 'concept'::public.curated_course_node_type, 'Dimensions, grain, numerator, denominator, time window, filters, targets, and benchmarks', null, 1),
  ('b29c7f08-4fb2-423d-8822-d17920ce620d', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '49643b59-47cf-47ae-a49e-dd84493dc373', 'concept'::public.curated_course_node_type, 'Occupancy, ADR, RevPAR, table turns, check average, labor cost, conversion, and satisfaction', null, 2),
  ('50bc2d2a-30f1-477f-aa3d-f42ee6754ba1', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'd8cbe598-154e-448f-9d23-796618c1b3a5', 'subtopic'::public.curated_course_node_type, 'Dashboards and decision workflows', 'This subtopic turns displays into tools for attention, diagnosis, action, ownership, and follow-through.', 1),
  ('29e505ff-992f-4481-88b0-b3948fd27884', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '50bc2d2a-30f1-477f-aa3d-f42ee6754ba1', 'concept'::public.curated_course_node_type, 'Executive, departmental, real-time, exception, diagnostic, and self-service views', null, 0),
  ('055283f0-b7a3-4a11-bd59-0b71ff788aa7', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '50bc2d2a-30f1-477f-aa3d-f42ee6754ba1', 'concept'::public.curated_course_node_type, 'Visual hierarchy, thresholds, alerts, drill-down, annotations, accessibility, and mobile use', null, 1),
  ('0334eb31-bbe9-4912-a7d0-52b415fea63e', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '50bc2d2a-30f1-477f-aa3d-f42ee6754ba1', 'concept'::public.curated_course_node_type, 'Decision cadence, meeting routines, owners, actions, due dates, and outcome tracking', null, 2),
  ('5f1a127f-de0d-43c9-94d5-04207ac048c6', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'd8cbe598-154e-448f-9d23-796618c1b3a5', 'subtopic'::public.curated_course_node_type, 'Experimentation and responsible AI', 'Students distinguish correlation, prediction, and causation and learn when models require testing and human oversight.', 2),
  ('8756065b-305f-4621-addb-02eac491582d', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '5f1a127f-de0d-43c9-94d5-04207ac048c6', 'concept'::public.curated_course_node_type, 'A/B tests, quasi-experiments, cohorts, confounding, uplift, and practical significance', null, 0),
  ('55843453-a673-4a66-93e7-62385a02c992', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '5f1a127f-de0d-43c9-94d5-04207ac048c6', 'concept'::public.curated_course_node_type, 'Prediction, classification, clustering, recommendations, generative AI, and process automation', null, 1),
  ('f583a495-6abe-4a54-b5c9-080be11f31b7', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '5f1a127f-de0d-43c9-94d5-04207ac048c6', 'concept'::public.curated_course_node_type, 'Training data, hallucination, privacy, bias, explainability, security, model monitoring, and NIST AI RMF', null, 2),
  ('2f8fec60-8b06-465b-8c5d-7265c224db07', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', null, 'topic'::public.curated_course_node_type, 'Payments, Finance, Controls, and Fraud', 'Hospitality systems handle money across desks, outlets, channels, currencies, and partners. This section links guest convenience to secure processing, accounting integrity, reconciliation, and loss prevention.', 8),
  ('d6264cbf-d3b6-46a4-99dd-92f79466dea3', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '2f8fec60-8b06-465b-8c5d-7265c224db07', 'subtopic'::public.curated_course_node_type, 'Payment lifecycle and architecture', 'Students trace authorization, capture, settlement, refund, and dispute across in-person and digital channels.', 0),
  ('2efd1e88-797c-4b29-8e25-69fe6f05bd85', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'd6264cbf-d3b6-46a4-99dd-92f79466dea3', 'concept'::public.curated_course_node_type, 'Cards, wallets, account-to-account, cash, gift cards, loyalty, direct billing, and charge-to-room', null, 0),
  ('39d7c44b-90ac-4b54-b8f0-ff1dbe5914bb', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'd6264cbf-d3b6-46a4-99dd-92f79466dea3', 'concept'::public.curated_course_node_type, 'Gateway, processor, acquirer, issuer, token, terminal, merchant account, and payment service provider', null, 1),
  ('3ceaa779-b56a-4719-a564-c8d6ab398950', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'd6264cbf-d3b6-46a4-99dd-92f79466dea3', 'concept'::public.curated_course_node_type, 'Card-present, card-not-present, preauthorization, incremental authorization, tips, deposits, and refunds', null, 2),
  ('73a239d6-73fa-4137-b275-48dff977703c', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '2f8fec60-8b06-465b-8c5d-7265c224db07', 'subtopic'::public.curated_course_node_type, 'Accounting interfaces and reconciliation', 'This subtopic ensures that operational activity can be proven against processor, bank, and ledger records.', 1),
  ('6526e177-6021-449d-a739-bdba62318de9', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '73a239d6-73fa-4137-b275-48dff977703c', 'concept'::public.curated_course_node_type, 'Daily close, revenue posting, taxes, fees, tips, commissions, receivables, and deposits', null, 0),
  ('0ec3ed74-bddb-4ff6-817b-4b9bcc568af2', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '73a239d6-73fa-4137-b275-48dff977703c', 'concept'::public.curated_course_node_type, 'PMS/POS subledgers, enterprise resource planning, general ledger, and bank feeds', null, 1),
  ('0ef8ebd5-e202-4655-b9fe-801cf72dd459', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '73a239d6-73fa-4137-b275-48dff977703c', 'concept'::public.curated_course_node_type, 'Control totals, settlement files, timing differences, suspense, exceptions, and audit evidence', null, 2),
  ('b5d4dbda-72ae-4dbe-8dc6-c92b5b31baae', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '2f8fec60-8b06-465b-8c5d-7265c224db07', 'subtopic'::public.curated_course_node_type, 'Security, compliance, and fraud controls', 'Students learn risk-based practices for reducing payment exposure without claiming to replace qualified compliance or security specialists.', 2),
  ('cf9fef63-e0c4-45b0-be9c-fc157cca7251', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'b5d4dbda-72ae-4dbe-8dc6-c92b5b31baae', 'concept'::public.curated_course_node_type, 'PCI DSS scope, tokenization, point-to-point encryption, segmentation, and vendor responsibility', null, 0),
  ('f90a6d24-9f97-4552-8fa6-b40be06d1003', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'b5d4dbda-72ae-4dbe-8dc6-c92b5b31baae', 'concept'::public.curated_course_node_type, 'Skimming, account testing, friendly fraud, chargebacks, refund abuse, loyalty fraud, and social engineering', null, 1),
  ('fd7dc3b1-48cc-4522-94f1-d661027c5d47', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'b5d4dbda-72ae-4dbe-8dc6-c92b5b31baae', 'concept'::public.curated_course_node_type, 'Least privilege, dual control, limits, alerts, case management, incident escalation, and evidence preservation', null, 2),
  ('813f88ca-89e7-411f-8970-ab88124d81ed', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', null, 'topic'::public.curated_course_node_type, 'Cybersecurity, Privacy, Continuity, and Technology Risk', 'Hospitality is a high-contact, always-on environment with sensitive identity and payment data. Students learn to govern technology risk as an operational and guest-trust responsibility.', 9),
  ('5c4d627b-32bf-4197-9fbe-c15fcc8a0f56', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '813f88ca-89e7-411f-8970-ab88124d81ed', 'subtopic'::public.curated_course_node_type, 'Cybersecurity risk management', 'Students apply a structured cycle to prioritize risks and communicate them in business terms.', 0),
  ('f635ea2d-0c40-435d-b407-bfa0d0332a36', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '5c4d627b-32bf-4197-9fbe-c15fcc8a0f56', 'concept'::public.curated_course_node_type, 'NIST CSF 2.0 functions: Govern, Identify, Protect, Detect, Respond, and Recover', null, 0);
