  ('2d6b5240-df8e-4e56-8831-886026678f04', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '5c4d627b-32bf-4197-9fbe-c15fcc8a0f56', 'concept'::public.curated_course_node_type, 'Assets, threats, vulnerabilities, likelihood, impact, controls, residual risk, and risk acceptance', null, 1),
  ('61ab0457-2c32-4184-9053-34528019fda4', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '5c4d627b-32bf-4197-9fbe-c15fcc8a0f56', 'concept'::public.curated_course_node_type, 'Identity, multifactor authentication, least privilege, patching, secure configuration, logging, and awareness', null, 2),
  ('4d5fcc1c-4ae5-42d6-8f8c-2f0db3b7ede7', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '813f88ca-89e7-411f-8970-ab88124d81ed', 'subtopic'::public.curated_course_node_type, 'Privacy and data governance', 'This subtopic treats privacy as a life-cycle discipline shaped by jurisdiction, purpose, guest expectations, and vendor relationships.', 1),
  ('e1b53bd8-db4d-470e-a4c8-6f200790390f', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '4d5fcc1c-4ae5-42d6-8f8c-2f0db3b7ede7', 'concept'::public.curated_course_node_type, 'Collection, notice, consent, use, sharing, retention, access, correction, deletion, and disposal', null, 0),
  ('21f36d6a-8c33-41c8-a0c3-f48b0947f67c', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '4d5fcc1c-4ae5-42d6-8f8c-2f0db3b7ede7', 'concept'::public.curated_course_node_type, 'Sensitive data, children, biometrics, location, profiling, cross-border transfers, and data-subject rights', null, 1),
  ('cb7c8a19-9043-46ea-add2-f5ed99e9897e', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '4d5fcc1c-4ae5-42d6-8f8c-2f0db3b7ede7', 'concept'::public.curated_course_node_type, 'Privacy impact assessments, records of processing, vendor clauses, breach duties, and counsel referral', null, 2),
  ('7019625d-74fe-4061-a078-be627a33f247', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '813f88ca-89e7-411f-8970-ab88124d81ed', 'subtopic'::public.curated_course_node_type, 'Continuity and incident response', 'Students prepare for system failure, cyber incidents, connectivity loss, and vendor outages while keeping essential service safe.', 2),
  ('2611eb57-076f-4d26-82a6-68b5202eba36', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '7019625d-74fe-4061-a078-be627a33f247', 'concept'::public.curated_course_node_type, 'Business impact analysis, recovery priorities, recovery time and recovery point objectives', null, 0),
  ('72da4667-ddf7-4e04-9c59-eb80db8d3a0d', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '7019625d-74fe-4061-a078-be627a33f247', 'concept'::public.curated_course_node_type, 'Manual operations, offline modes, backups, alternate communications, emergency access, and restoration', null, 1),
  ('64efdab1-cbd0-49e6-a95a-5e0dfb8e8712', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '7019625d-74fe-4061-a078-be627a33f247', 'concept'::public.curated_course_node_type, 'Incident roles, triage, containment, legal and insurer escalation, guest communications, lessons learned', null, 2),
  ('b077edb0-ce50-4307-bc04-1c4cc2039a6e', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', null, 'topic'::public.curated_course_node_type, 'Mobile, Contactless, IoT, and Inclusive Guest Experience', 'Digital convenience succeeds only when it is reliable, usable, accessible, secure, and supported by a human alternative. Students evaluate technology through the complete guest and employee journey.', 10),
  ('22383a67-f952-4eca-a917-3f321d4e311e', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'b077edb0-ce50-4307-bc04-1c4cc2039a6e', 'subtopic'::public.curated_course_node_type, 'Mobile and self-service journeys', 'Students design digital touchpoints that reduce friction without transferring hidden work or risk to the guest.', 0),
  ('86a067f5-fc16-4562-87ad-719f50714571', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '22383a67-f952-4eca-a917-3f321d4e311e', 'concept'::public.curated_course_node_type, 'Mobile booking, check-in, identity verification, digital keys, messaging, ordering, payment, and checkout', null, 0),
  ('d4fccd62-4ee9-4be3-9564-da9df601fe85', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '22383a67-f952-4eca-a917-3f321d4e311e', 'concept'::public.curated_course_node_type, 'Kiosks, QR interactions, chat, virtual concierge, queue management, and wayfinding', null, 1),
  ('d1c5bae1-9a04-4e2a-a4eb-6fd8f83d17c0', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '22383a67-f952-4eca-a917-3f321d4e311e', 'concept'::public.curated_course_node_type, 'Failure recovery, assisted service, device compatibility, language, connectivity, and adoption', null, 2),
  ('b92545b1-c5e1-4913-b298-bb5ee83afb6f', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'b077edb0-ce50-4307-bc04-1c4cc2039a6e', 'subtopic'::public.curated_course_node_type, 'IoT, smart rooms, facilities, and energy', 'This subtopic connects sensors and controls to comfort, maintenance, safety, and environmental performance.', 1),
  ('e01bdb95-06e0-4281-a95f-dc6a1ab5fd16', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'b92545b1-c5e1-4913-b298-bb5ee83afb6f', 'concept'::public.curated_course_node_type, 'Locks, thermostats, lighting, occupancy, air quality, water, elevators, and building systems', null, 0),
  ('60d9b855-9c14-47c0-880a-13684557eb25', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'b92545b1-c5e1-4913-b298-bb5ee83afb6f', 'concept'::public.curated_course_node_type, 'Device identity, gateways, protocols, telemetry, remote management, firmware, and segmentation', null, 1),
  ('7f7169b4-8536-4173-8c2c-b558d92a516b', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'b92545b1-c5e1-4913-b298-bb5ee83afb6f', 'concept'::public.curated_course_node_type, 'Predictive maintenance, demand response, energy optimization, alerts, overrides, and commissioning', null, 2),
  ('b88a7caa-e204-4c78-a857-b24fc3e03ddf', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'b077edb0-ce50-4307-bc04-1c4cc2039a6e', 'subtopic'::public.curated_course_node_type, 'Accessibility, inclusion, and service ethics', 'Students use inclusive design to make technology workable for diverse bodies, senses, languages, abilities, contexts, and levels of digital confidence.', 2),
  ('8141bfc8-9136-46d7-95c4-5e4ec70e3ab0', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'b88a7caa-e204-4c78-a857-b24fc3e03ddf', 'concept'::public.curated_course_node_type, 'Perceivable, operable, understandable, and robust digital experiences', null, 0),
  ('87145f37-0c9c-471f-95ff-bfc1009260d1', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'b88a7caa-e204-4c78-a857-b24fc3e03ddf', 'concept'::public.curated_course_node_type, 'Captions, contrast, keyboard access, screen readers, plain language, accessible authentication, and testing', null, 1),
  ('8af1f755-cf52-4d66-af60-dd42de601c0a', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'b88a7caa-e204-4c78-a857-b24fc3e03ddf', 'concept'::public.curated_course_node_type, 'Cash and human alternatives, dignity, non-discrimination, consent, surveillance concerns, and service recovery', null, 2),
  ('ca8ac642-caf3-407f-aba9-ffb6b600c426', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', null, 'topic'::public.curated_course_node_type, 'Technology Selection, Vendor Management, and Business Cases', 'Choosing technology is a disciplined organizational decision. This section teaches students to translate needs into evidence, compare whole-life value, and negotiate accountable partnerships.', 11),
  ('c1c7d444-9bfd-45ef-991a-012bdc19c8a5', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'ca8ac642-caf3-407f-aba9-ffb6b600c426', 'subtopic'::public.curated_course_node_type, 'Requirements and market discovery', 'Students separate mandatory capabilities and constraints from attractive but low-value features.', 0),
  ('c34931a1-d732-4c96-967c-2f2de4f63ce6', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'c1c7d444-9bfd-45ef-991a-012bdc19c8a5', 'concept'::public.curated_course_node_type, 'Stakeholders, personas, process maps, pain points, jobs to be done, and future-state design', null, 0),
  ('ce22baed-bb36-4f61-a1ef-7d08b4123a9a', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'c1c7d444-9bfd-45ef-991a-012bdc19c8a5', 'concept'::public.curated_course_node_type, 'Functional, data, integration, security, privacy, accessibility, performance, support, and compliance requirements', null, 1),
  ('13ffcca3-6379-4271-a4b2-c0aeb6dc04ca', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'c1c7d444-9bfd-45ef-991a-012bdc19c8a5', 'concept'::public.curated_course_node_type, 'Request for information, market scan, references, demonstrations, sandbox trials, and proof of concept', null, 2),
  ('4777d22e-9df3-4760-8143-894a0a02ede2', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'ca8ac642-caf3-407f-aba9-ffb6b600c426', 'subtopic'::public.curated_course_node_type, 'Evaluation and business case', 'This subtopic combines quantitative and qualitative evidence into a transparent recommendation.', 1),
  ('24197aa9-f1c7-4443-ab77-ffe242d06ed4', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '4777d22e-9df3-4760-8143-894a0a02ede2', 'concept'::public.curated_course_node_type, 'Weighted criteria, scripted demos, use cases, scoring anchors, fit-gap analysis, and bias controls', null, 0),
  ('35e6bd88-66c5-4ac2-bd67-90275db1ce92', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '4777d22e-9df3-4760-8143-894a0a02ede2', 'concept'::public.curated_course_node_type, 'Acquisition, implementation, interfaces, hardware, training, support, upgrades, exit, and total cost', null, 1),
  ('ad2eb0d4-ad80-4628-b405-9abbfe7bebe3', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '4777d22e-9df3-4760-8143-894a0a02ede2', 'concept'::public.curated_course_node_type, 'Benefits, baseline, sensitivity, risk-adjusted value, payback, governance, and benefits owner', null, 2),
  ('ef5e9ebd-2a58-44c1-91b6-0fb2d9404639', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'ca8ac642-caf3-407f-aba9-ffb6b600c426', 'subtopic'::public.curated_course_node_type, 'Contracts and vendor governance', 'Students learn the commercial and operational terms that sustain performance after the sale.', 2),
  ('3fc43124-5205-4a8f-964e-900f99e2bb24', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'ef5e9ebd-2a58-44c1-91b6-0fb2d9404639', 'concept'::public.curated_course_node_type, 'Scope, deliverables, milestones, acceptance, fees, renewals, change control, and warranties', null, 0),
  ('0283d27b-3ace-4df1-bfe5-a0abf14f9b78', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'ef5e9ebd-2a58-44c1-91b6-0fb2d9404639', 'concept'::public.curated_course_node_type, 'Service levels, uptime, support, security, data processing, insurance, indemnity, audit, and breach notification', null, 1),
  ('10c3e2f8-fddd-4cd7-90a4-dbf8dc24d034', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'ef5e9ebd-2a58-44c1-91b6-0fb2d9404639', 'concept'::public.curated_course_node_type, 'Data portability, integration access, subcontractors, benchmarking, termination, transition assistance, and vendor lock-in', null, 2),
  ('ebd4e2d1-e96a-4833-8098-b15b86b78f41', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', null, 'topic'::public.curated_course_node_type, 'Implementation, Change Management, and Adoption', 'Even good technology fails when workflow, configuration, training, incentives, and support are misaligned. Students learn to plan implementation as an operating-model change.', 12),
  ('ea504436-812a-4c88-9fff-6cbeb7018e3b', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'ebd4e2d1-e96a-4833-8098-b15b86b78f41', 'subtopic'::public.curated_course_node_type, 'Implementation lifecycle', 'Students organize discovery through stabilization using explicit gates, ownership, evidence, and risk controls.', 0),
  ('c16a5ef1-a6b4-49c8-8560-ee9a7460dd20', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'ea504436-812a-4c88-9fff-6cbeb7018e3b', 'concept'::public.curated_course_node_type, 'Charter, governance, scope, plan, budget, risks, issues, decisions, and change control', null, 0),
  ('57c81a5a-54d5-4590-9c72-485dba408458', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'ea504436-812a-4c88-9fff-6cbeb7018e3b', 'concept'::public.curated_course_node_type, 'Configuration, interfaces, data migration, testing, training, cutover, rollback, and hypercare', null, 1);
