values
  ('c845ab85-6c2a-4e51-b8fa-5e3389e552fc', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'ea504436-812a-4c88-9fff-6cbeb7018e3b', 'concept'::public.curated_course_node_type, 'Waterfall, agile, pilot, phased, parallel, and big-bang approaches', null, 2),
  ('554a1f24-7794-408e-b3e0-86cd51baa886', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'ebd4e2d1-e96a-4833-8098-b15b86b78f41', 'subtopic'::public.curated_course_node_type, 'Data migration, testing, and readiness', 'This subtopic protects operations by proving data, workflows, controls, and support before launch.', 1),
  ('d79886ef-e369-47c8-a0a2-391afd5944c3', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '554a1f24-7794-408e-b3e0-86cd51baa886', 'concept'::public.curated_course_node_type, 'Extract, cleanse, map, transform, load, reconcile, archive, and retention', null, 0),
  ('71965695-a289-40ec-8b9f-4eb7dbed1af1', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '554a1f24-7794-408e-b3e0-86cd51baa886', 'concept'::public.curated_course_node_type, 'Unit, integration, end-to-end, security, performance, accessibility, recovery, and user acceptance tests', null, 1),
  ('9613d592-0013-4e0c-9b8a-c7f92ec4b24c', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '554a1f24-7794-408e-b3e0-86cd51baa886', 'concept'::public.curated_course_node_type, 'Go-live criteria, defect severity, rehearsals, contingency, readiness dashboard, and sign-off', null, 2),
  ('bdfe742a-4206-45b6-99c2-2facbabd907a', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'ebd4e2d1-e96a-4833-8098-b15b86b78f41', 'subtopic'::public.curated_course_node_type, 'Change, learning, and benefits realization', 'Students plan for behavior, capability, and ownership—not just system availability.', 2),
  ('94a671e8-21ca-4a9e-a9aa-eb0257af712e', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'bdfe742a-4206-45b6-99c2-2facbabd907a', 'concept'::public.curated_course_node_type, 'Stakeholder impact, sponsors, champions, resistance, communications, feedback, and psychological safety', null, 0),
  ('c5db00e6-e5c6-41d3-977b-9d7caafe00c9', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'bdfe742a-4206-45b6-99c2-2facbabd907a', 'concept'::public.curated_course_node_type, 'Role-based learning, practice environment, job aids, coaching, proficiency, and support model', null, 1),
  ('b15a5a76-3b75-4714-8f34-fc383b62ec43', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'bdfe742a-4206-45b6-99c2-2facbabd907a', 'concept'::public.curated_course_node_type, 'Adoption measures, process compliance, benefit measures, post-implementation review, and continuous improvement', null, 2),
  ('aba95729-c16d-4aa9-a6b4-0074a93b63df', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', null, 'topic'::public.curated_course_node_type, 'Innovation, Responsible Technology, and the Future of Hospitality', 'The final section helps students investigate emerging technology without hype. They learn to test strategic relevance, operational feasibility, stakeholder impacts, and ethical boundaries.', 13),
  ('506f984c-6ead-4dea-ba46-0378b742c5fc', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'aba95729-c16d-4aa9-a6b4-0074a93b63df', 'subtopic'::public.curated_course_node_type, 'Technology sensing and scenario analysis', 'Students build a repeatable process for recognizing signals and examining plausible futures.', 0),
  ('30ba81a2-f7bf-470f-a919-7d5db06b68a5', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '506f984c-6ead-4dea-ba46-0378b742c5fc', 'concept'::public.curated_course_node_type, 'AI agents, robotics, biometrics, spatial computing, digital identity, autonomous operations, and new platforms', null, 0),
  ('456efb80-9624-4656-b201-e0a5d44ed9c3', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '506f984c-6ead-4dea-ba46-0378b742c5fc', 'concept'::public.curated_course_node_type, 'Horizon scanning, trend evidence, maturity, diffusion, dependencies, and uncertainty', null, 1),
  ('82dbb206-fad9-4563-9a6d-2002b0917ff9', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '506f984c-6ead-4dea-ba46-0378b742c5fc', 'concept'::public.curated_course_node_type, 'Scenarios, signposts, options, experiments, stop criteria, and portfolio balance', null, 2),
  ('994de3c3-fa0d-4661-a16f-2ec6f5a65a4c', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'aba95729-c16d-4aa9-a6b4-0074a93b63df', 'subtopic'::public.curated_course_node_type, 'Responsible innovation', 'This subtopic makes values, affected groups, and potential harms part of the design decision.', 1),
  ('615aaa9c-0928-4cec-bc40-7eda893c0930', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '994de3c3-fa0d-4661-a16f-2ec6f5a65a4c', 'concept'::public.curated_course_node_type, 'Guest and employee participation, accessibility, labor impacts, deskilling, and power', null, 0),
  ('44c42878-560b-4901-ba96-1d9673ee2e44', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '994de3c3-fa0d-4661-a16f-2ec6f5a65a4c', 'concept'::public.curated_course_node_type, 'Privacy, bias, security, safety, explainability, contestability, and human oversight', null, 1),
  ('bca3a2d3-b35d-4b0b-8a8b-3a09e8a41d5a', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', '994de3c3-fa0d-4661-a16f-2ec6f5a65a4c', 'concept'::public.curated_course_node_type, 'Responsible AI governance, impact assessment, red teams, monitoring, appeals, and retirement', null, 2),
  ('b55946c6-a839-4cde-bc95-0fcf93af1a36', 'd9e0f1a2-3b4c-4d14-9e63-7f8a9b0c1d04', 'aba95729-c16d-4aa9-a6b4-0074a93b63df', 'subtopic'::public.curated_course_node_type, 'Sustainability and shared value', 'Students evaluate whether technology improves environmental and social outcomes across its full life cycle.', 2),
