select
  'hospitality-information-systems',
  null,
  'Hospitality Information Systems',
  'Hospitality Information Systems',
  'This course prepares hospitality managers to select, govern, implement, use, integrate, and improve information systems across lodging, foodservice, commercial, guest-experience, and enterprise operations. Students investigate PMS, POS, CRS and distribution, CRM and loyalty, RMS, payments, data and APIs, analytics and AI, mobile and IoT experiences, cybersecurity and privacy, vendor management, and organizational change. The emphasis is managerial fluency: mapping workflows, interpreting system data, evaluating controls and tradeoffs, designing inclusive service, questioning automated recommendations, and building an evidence-based technology roadmap.',
  $hisyjson${"slug": "hospitality-information-systems", "title": "Hospitality Information Systems", "description": "This course prepares hospitality managers to select, govern, implement, use, integrate, and improve information systems across lodging, foodservice, commercial, guest-experience, and enterprise operations. Students investigate PMS, POS, CRS and distribution, CRM and loyalty, RMS, payments, data and APIs, analytics and AI, mobile and IoT experiences, cybersecurity and privacy, vendor management, and organizational change. The emphasis is managerial fluency: mapping workflows, interpreting system data, evaluating controls and tradeoffs, designing inclusive service, questioning automated recommendations, and building an evidence-based technology roadmap.", "topics": [{"id": "7ccc3537-d317-4dc5-bb86-8896b5f3b540", "type": "topic", "title": "Hospitality Digital Ecosystem and Systems Thinking", "description": "Hospitality technology is a connected service system, not a collection of isolated applications. This section gives students a managerial map of how people, processes, data, devices, vendors, and platforms combine to deliver the guest experience and business performance.", "children": [{"id": "b4274d5b-e2a3-44f5-84d9-fa1fd3d6ac36", "type": "subtopic", "title": "Enterprise and property technology landscape", "children": [{"id": "3c9b83a5-1fd4-41c1-bb1f-4e6711f477ef", "type": "concept", "title": "Guest-facing, operational, commercial, financial, workforce, facilities, and enterprise systems"}, {"id": "07f286f2-c4c2-452e-933f-2168fba1b4e2", "type": "concept", "title": "Property, cluster, brand, owner, franchise, management-company, and third-party perspectives"}, {"id": "cdb84a67-4950-4428-b610-c49dec3aa058", "type": "concept", "title": "Cloud, on-premises, edge, mobile, software-as-a-service, and platform models"}], "description": "Students learn the major layers of a hotel, resort, restaurant, and multi-property technology stack so they can locate a problem before proposing a tool."}, {"id": "0392e43a-3a93-457d-b9b8-927f2000876f", "type": "subtopic", "title": "Systems thinking and service processes", "children": [{"id": "d5bb19d1-3a75-407f-9d0d-bdfc43184f72", "type": "concept", "title": "Inputs, activities, handoffs, controls, outputs, outcomes, and feedback loops"}, {"id": "5ab480d9-82f4-4750-b8fa-73fb28f5b5cf", "type": "concept", "title": "Service blueprinting across frontstage, backstage, and support processes"}, {"id": "7819dc98-22ed-4803-b0fd-3f55e4ea50bf", "type": "concept", "title": "Bottlenecks, failure demand, workarounds, automation opportunities, and unintended consequences"}], "description": "This subtopic connects technology choices to the end-to-end work that creates value for guests and employees."}, {"id": "7d8b4eb9-e616-4180-a721-32f92b8ddc21", "type": "subtopic", "title": "Technology strategy and value", "children": [{"id": "ac45e3f6-b246-4421-9561-bcfa7ea5bbd2", "type": "concept", "title": "Strategic alignment, differentiation, standardization, scalability, and operating-model fit"}, {"id": "1b167c4c-40a5-452a-86a7-533c51a8420a", "type": "concept", "title": "Revenue, cost, productivity, quality, risk, resilience, accessibility, and sustainability value"}, {"id": "8eea02ff-455f-4905-9d33-2d0bc42dd613", "type": "concept", "title": "Total cost of ownership, opportunity cost, benefits realization, and technical debt"}], "description": "Students frame technology as an investment in capabilities and outcomes rather than as a feature checklist."}]}, {"id": "7359a7fe-7339-43ac-b2d7-be24bd43f73d", "type": "topic", "title": "Property Management Systems and Lodging Operations", "description": "The property management system is the operational hub of lodging. Students learn the guest-account and room-inventory logic behind the screens so they can design controls, diagnose exceptions, and improve service.", "children": [{"id": "072bd533-baa7-4a6c-943c-11ca07bb87dd", "type": "subtopic", "title": "Reservation-to-departure workflow", "children": [{"id": "4d2f8d19-e72c-4832-990b-fa9cdd0a396e", "type": "concept", "title": "Availability search, reservation, guarantee, deposit, modification, cancellation, and no-show"}, {"id": "eac885e4-8516-46ca-b02d-28b8336e75dc", "type": "concept", "title": "Pre-arrival, registration, room assignment, keys, check-in, stay changes, and check-out"}, {"id": "f91792d7-8554-47ce-96c5-8e5ece89b9ad", "type": "concept", "title": "Walks, overbooking, room moves, split stays, extensions, early departures, and service recovery"}], "description": "Students trace the guest record and stay through its full life cycle, including the exceptions that expose weak processes."}, {"id": "ab2d6d58-10bd-408f-8fee-af8e41b24522", "type": "subtopic", "title": "Rooms, rates, folios, and night audit", "children": [{"id": "b68f26b1-8f6d-45b2-90c7-cd98eaae3ba3", "type": "concept", "title": "Room types, room status, housekeeping, out-of-order, and maintenance coordination"}, {"id": "d826a910-cb3a-4728-bd5e-864417848432", "type": "concept", "title": "Rate plans, packages, restrictions, routing, allowances, taxes, fees, and folio windows"}, {"id": "18ce4e3d-6ddb-44f5-a48d-f60346991f3b", "type": "concept", "title": "Night audit, business date, interface reconciliation, exception reports, and audit trail"}], "description": "This subtopic explains the operational data structures that support inventory control, posting, settlement, and daily close."}, {"id": "d39585db-9a2d-4ed8-b515-fd2a1c3025cb", "type": "subtopic", "title": "Multi-property and stakeholder controls", "children": [{"id": "e537a5c1-189b-43ba-9bdb-7a57c81df55b", "type": "concept", "title": "Chain codes, property configuration, user roles, approvals, and segregation of duties"}, {"id": "f116aa41-2747-4d76-9871-1a5fd20887fd", "type": "concept", "title": "Profiles, negotiated rates, group blocks, allotments, and central services"}, {"id": "e2e3cdc9-7cc6-442e-aa17-96dd4fbdd7e0", "type": "concept", "title": "Standard operating procedures, data ownership, support tiers, and property-level autonomy"}], "description": "Students examine how PMS configuration and access differ across ownership, brand, management, and regional structures."}]}, {"id": "fb17a2e3-4c39-4216-9077-073c2e9f4284", "type": "topic", "title": "Point-of-Sale, Foodservice, Inventory, and Procurement Systems", "description": "Food-and-beverage systems join guest service with production, inventory, labor, payments, and accounting. This section prepares students to evaluate both front-of-house speed and back-of-house control.", "children": [{"id": "cfbd1139-fa59-4797-975b-6a4d855e02e9", "type": "subtopic", "title": "POS transaction and service design", "children": [{"id": "eab00706-b407-4adb-8a89-20c7b5a334fc", "type": "concept", "title": "Menu hierarchy, modifiers, pricing, discounts, comps, voids, tips, and taxes"}, {"id": "14fe8444-7c3f-4285-b59c-9e549ae180cc", "type": "concept", "title": "Table service, quick service, bars, banquets, kiosks, mobile ordering, and delivery"}, {"id": "eefcff55-9b86-46fb-9d33-cc29321d9147", "type": "concept", "title": "Kitchen display, printers, coursing, checks, split tender, offline mode, and closeout"}], "description": "Students connect menu design and service style to ordering, routing, fulfillment, payment, and recovery workflows."}, {"id": "75882426-308d-4160-a986-1d1d9769ed05", "type": "subtopic", "title": "Inventory, recipe, and cost control", "children": [{"id": "e8d5b76d-5cb2-463e-9fd5-c72d15800869", "type": "concept", "title": "Recipes, yields, portions, theoretical versus actual usage, and menu engineering"}, {"id": "c303ceeb-b9a9-4a00-a228-4a662bc44216", "type": "concept", "title": "Purchasing, receiving, transfers, counts, waste, spoilage, and variance"}, {"id": "65546de2-a05d-449d-a182-75cca547c0a8", "type": "concept", "title": "Reorder points, par levels, vendor catalogs, traceability, and food-safety records"}], "description": "This subtopic uses systems data to protect margin, availability, quality, and traceability."}, {"id": "5dc9966e-7679-46b5-b5fc-bbb8729d3dec", "type": "subtopic", "title": "Labor, procurement, and accounting integration", "children": [{"id": "0b85a9bb-bc6e-4edf-917c-9735ae0de719", "type": "concept", "title": "Demand-based scheduling, timekeeping, payroll interfaces, and labor productivity"}, {"id": "15178cae-55c0-489b-a124-193c4f8888e3", "type": "concept", "title": "Requisitions, purchase orders, approvals, invoices, three-way match, and e-procurement"}, {"id": "1d3a59bf-11f2-4710-ad95-b568902a70c5", "type": "concept", "title": "Revenue centers, tenders, taxes, tips, charge-to-room, and general-ledger mapping"}], "description": "Students learn how operational transactions become schedules, liabilities, journal entries, and management reports."}]}, {"id": "b05b5755-cfeb-445a-84bb-e843e9c6d371", "type": "topic", "title": "Reservations, Distribution, and Digital Commerce", "description": "A room or table may be sold through many intermediaries. Students learn how availability, rates, content, identity, and economics move across the distribution network—and where errors or conflicts arise.", "children": [{"id": "6031eeee-2422-4f84-8453-45ea4cd9fc84", "type": "subtopic", "title": "CRS, booking engine, GDS, and channel architecture", "children": [{"id": "61bf6a8b-c78c-4965-9873-7ecf55869e32", "type": "concept", "title": "Central reservation system, internet booking engine, call center, and property inventory"}, {"id": "47be1b4f-eac4-4f56-81a1-3940fb645e8f", "type": "concept", "title": "Global distribution systems, online travel agencies, wholesalers, bedbanks, and tour operators"}, {"id": "a3c98550-c7eb-435f-824a-bc1e992552a0", "type": "concept", "title": "Channel managers, switches, metasearch, super apps, and connectivity providers"}], "description": "Students map the systems and messages that connect inventory to direct and indirect demand."}, {"id": "380051f0-59b7-4d1a-8a49-d630ea114f3c", "type": "subtopic", "title": "Content, rate, and inventory synchronization", "children": [{"id": "ee411603-5751-4a4e-b994-0f0d59e600df", "type": "concept", "title": "Room and rate mapping, descriptions, images, policies, amenities, and accessibility attributes"}, {"id": "6e1c8d4c-2ffe-4172-b5af-142ae3a36b25", "type": "concept", "title": "Availability, rates, inventory, restrictions, promotions, and stop-sell messages"}, {"id": "e3e80dd5-dfb7-421d-ad96-1091d6825c07", "type": "concept", "title": "Latency, oversell, stale content, parity, caching, reconciliation, and exception monitoring"}], "description": "This subtopic focuses on accurate, timely distribution of products and restrictions across channels."}, {"id": "c132fa84-1471-4356-a58f-c74ad1e81875", "type": "subtopic", "title": "Distribution economics and control", "children": [{"id": "00f186a7-97f8-4632-9eb7-38696501dade", "type": "concept", "title": "Direct versus intermediary economics, net rates, commissions, merchant and agency models"}, {"id": "1f85f800-ba0f-4ce4-98ca-71d3691aa2d9", "type": "concept", "title": "Attribution, conversion, cancellation, no-show, refund, chargeback, and lifetime value"}, {"id": "754cb56c-e69c-451a-8e28-42845999f657", "type": "concept", "title": "Channel mix, parity rules, loyalty/member rates, governance, and ethical consumer disclosure"}], "description": "Students compare reach and conversion with commissions, acquisition costs, data access, and dependency risk."}]}, {"id": "291fdb66-5d2f-496d-ae70-dbfe03ffb0c7", "type": "topic", "title": "Guest Data, CRM, Loyalty, and Personalization", "description": "Guest relationships depend on trustworthy identity, permission, and context. This section teaches students to create relevant experiences without turning personalization into surveillance or discrimination.", "children": [{"id": "2bea998e-a831-4063-ba11-476d71fa192c", "type": "subtopic", "title": "Guest identity and profile management", "children": [{"id": "45c439f2-df03-4b3f-853e-51391d19aa67", "type": "concept", "title": "Identifiers, duplicates, household and company relationships, preferences, and consent"}, {"id": "43143bab-fdcc-4b08-8b4e-6d05e5b4fb5a", "type": "concept", "title": "PMS profiles, CRM, customer data platforms, loyalty databases, and identity resolution"}, {"id": "db136b47-0655-412d-b07e-57ad8cafc45f", "type": "concept", "title": "Golden records, match rules, survivorship, provenance, data quality, and deletion"}], "description": "Students learn how profiles are created, matched, merged, enriched, and governed across stays and channels."}, {"id": "56820edb-3fec-4221-836d-3ba9d46b1894", "type": "subtopic", "title": "CRM and loyalty operations", "children": [{"id": "031630b7-bdc6-4667-9bd6-ed488c4e7306", "type": "concept", "title": "Segmentation, lifecycle journeys, campaigns, cases, tasks, and service recovery"}, {"id": "36a34323-8e85-4a96-a8db-7b69fb8f7be1", "type": "concept", "title": "Enrollment, tiers, earn and burn, benefits, partnerships, liability, and fraud"}, {"id": "17d4cedb-3938-4e32-99fa-d2bedc74075a", "type": "concept", "title": "Engagement, repeat behavior, churn, redemption, incremental value, and program economics"}], "description": "This subtopic connects guest data to acquisition, service, retention, recovery, and relationship value."}, {"id": "59885c21-9fd3-4e80-b4b0-3acfa48a75e1", "type": "subtopic", "title": "Responsible personalization", "children": [{"id": "40ed6ddf-66e8-412f-a89d-7de2c9fa6e3d", "type": "concept", "title": "Next-best action, recommendations, preference fulfillment, and human override"}, {"id": "bff67d89-32b7-4a99-894f-6531e95e8496", "type": "concept", "title": "Consent, transparency, data minimization, purpose limitation, and sensitive attributes"}, {"id": "a69b23e9-a0db-41af-90a8-61bc0dbcce08", "type": "concept", "title": "Bias testing, exclusion, vulnerable guests, accessibility, complaint handling, and opt-out"}], "description": "Students design relevant offers and service prompts while respecting choice, fairness, dignity, and context."}]}, {"id": "d11312ca-323c-48f3-aa11-aebd8d2c0da7", "type": "topic", "title": "Revenue Management Systems and Commercial Decision Support", "description": "Revenue systems turn demand signals, capacity, price, and controls into commercial recommendations. Students learn both the analytical logic and the managerial responsibility to challenge outputs.", "children": [{"id": "90b6ed11-5921-4062-b929-3b7c1214adba", "type": "subtopic", "title": "Forecasting and demand signals", "children": [{"id": "86c50f45-4698-4f0d-b02f-cf009528d6b0", "type": "concept", "title": "Bookings, pace, pickup, cancellations, no-shows, length of stay, and lead time"}, {"id": "eff7f3f6-7a49-4d92-8cff-65860acab94e", "type": "concept", "title": "Events, holidays, competitors, search, web traffic, weather, and market intelligence"}, {"id": "a3795385-ce0f-4180-bf66-b975fff4e14c", "type": "concept", "title": "Forecast horizon, granularity, seasonality, outliers, scenario ranges, and forecast error"}], "description": "Students examine how systems estimate unconstrained demand and uncertainty from internal and external evidence."}, {"id": "c65a7bdc-19c7-4d48-a9ef-edcc2cca2833", "type": "subtopic", "title": "Optimization, pricing, and inventory controls", "children": [{"id": "649c23fc-384b-4f48-9f5b-f63e35013ba5", "type": "concept", "title": "Segments, willingness to pay, price sensitivity, rate fences, and dynamic pricing"}, {"id": "518a972e-9bd4-47fe-aaad-9ecd8ea9682a", "type": "concept", "title": "Overbooking, minimum stay, closed-to-arrival, nested inventory, and displacement"}, {"id": "3c5b1528-208a-4a57-ae13-8e41683bca0d", "type": "concept", "title": "Group evaluation, bid price, upgrades, ancillary revenue, and total revenue management"}], "description": "This subtopic explains how RMS recommendations influence price, availability, and acceptance decisions."}, {"id": "df09010e-00e3-4874-861e-4f14f9e5088d", "type": "subtopic", "title": "Governance and performance", "children": [{"id": "2abd8c96-8338-4f54-ac77-d48fa1a1ed3d", "type": "concept", "title": "ADR, occupancy, RevPAR, TRevPAR, GOPPAR, contribution, and channel cost"}, {"id": "7c954d21-9ccf-4103-b635-7e5905b54461", "type": "concept", "title": "Overrides, reason codes, alerts, thresholds, approval rights, and revenue meetings"}, {"id": "036ddb31-a016-4344-b1a7-1379d4fc760b", "type": "concept", "title": "Model drift, feedback loops, price fairness, collusion risk, explainability, and human accountability"}], "description": "Students learn to monitor model outputs and commercial outcomes rather than treating automation as unquestionable authority."}]}, {"id": "6afa374e-142c-4d24-9570-9e54debf3ce3", "type": "topic", "title": "Data Architecture, Integration, APIs, and Interoperability", "description": "Reliable hospitality operations depend on systems exchanging consistent data at the right time. This section gives managers enough technical fluency to specify integrations, recognize failure modes, and ask better questions.", "children": [{"id": "2a329080-22a7-4f68-bcb5-0983ab852830", "type": "subtopic", "title": "Data models and master data", "children": [{"id": "b9a621a1-24fc-4c17-a12c-ec71eeaf6728", "type": "concept", "title": "Guests, reservations, stays, rooms, rates, outlets, products, employees, vendors, and transactions"}, {"id": "82a09422-2db9-4fdc-bedc-98853eac3900", "type": "concept", "title": "Master, reference, transactional, event, document, and analytical data"}, {"id": "4a98cde4-b274-464e-97a7-dd7a8772ddd8", "type": "concept", "title": "Data dictionary, metadata, ownership, lineage, retention, quality rules, and stewardship"}], "description": "Students learn why shared definitions and identifiers are prerequisites for trustworthy transactions and analytics."}, {"id": "838c702e-af8b-4277-8b09-a8cd5be6b22d", "type": "subtopic", "title": "Integration patterns and APIs", "children": [{"id": "2ad90e1e-17c9-4cb1-8ad6-e61ea8e4f071", "type": "concept", "title": "Files, batches, queues, webhooks, application programming interfaces, and event streams"}, {"id": "2d57d500-36be-4870-9fd8-04cd03be2540", "type": "concept", "title": "Requests, responses, authentication, schemas, mappings, validation, retries, and idempotency"}, {"id": "2c5645a9-6827-4604-9194-ae2cf84f2d28", "type": "concept", "title": "Point-to-point, middleware, integration platforms, microservices, and vendor marketplaces"}], "description": "This subtopic introduces the main ways systems communicate and the tradeoffs among speed, reliability, and complexity."}, {"id": "760427d8-5db4-4bbc-ad38-c088487f7de4", "type": "subtopic", "title": "Interoperability and operational resilience", "children": [{"id": "0ef63b22-8787-4b39-9dbf-589b7fe1c5c1", "type": "concept", "title": "Hospitality standards and shared schemas from HTNG and OpenTravel communities"}, {"id": "9bd5af0a-ee6f-4a8b-b04d-16601e15aa3c", "type": "concept", "title": "Latency, duplication, ordering, partial failure, reconciliation, observability, and audit logs"}, {"id": "04682a5c-c000-4389-83bb-99f5edda6956", "type": "concept", "title": "Sandbox, test cases, cutover, rollback, offline procedures, service levels, and support ownership"}], "description": "Students test integrations as business processes, including exceptions and recovery—not merely as successful message transfers."}]}, {"id": "d8cbe598-154e-448f-9d23-796618c1b3a5", "type": "topic", "title": "Analytics, Business Intelligence, Experimentation, and AI", "description": "Hospitality data becomes valuable only when it improves a decision. Students learn to frame questions, build defensible metrics, interpret evidence, and use automation with appropriate skepticism.", "children": [{"id": "49643b59-47cf-47ae-a49e-dd84493dc373", "type": "subtopic", "title": "Metrics and semantic consistency", "children": [{"id": "6e5d6652-1e90-4420-8795-122a39b45cd1", "type": "concept", "title": "Operational, guest, commercial, financial, workforce, sustainability, and risk measures"}, {"id": "7aa7f76a-bbe3-4de1-8ba6-6c7e0f5407fc", "type": "concept", "title": "Dimensions, grain, numerator, denominator, time window, filters, targets, and benchmarks"}, {"id": "b29c7f08-4fb2-423d-8822-d17920ce620d", "type": "concept", "title": "Occupancy, ADR, RevPAR, table turns, check average, labor cost, conversion, and satisfaction"}], "description": "Students define performance measures so teams do not make decisions from conflicting versions of the truth."}, {"id": "50bc2d2a-30f1-477f-aa3d-f42ee6754ba1", "type": "subtopic", "title": "Dashboards and decision workflows", "children": [{"id": "29e505ff-992f-4481-88b0-b3948fd27884", "type": "concept", "title": "Executive, departmental, real-time, exception, diagnostic, and self-service views"}, {"id": "055283f0-b7a3-4a11-bd59-0b71ff788aa7", "type": "concept", "title": "Visual hierarchy, thresholds, alerts, drill-down, annotations, accessibility, and mobile use"}, {"id": "0334eb31-bbe9-4912-a7d0-52b415fea63e", "type": "concept", "title": "Decision cadence, meeting routines, owners, actions, due dates, and outcome tracking"}], "description": "This subtopic turns displays into tools for attention, diagnosis, action, ownership, and follow-through."}, {"id": "5f1a127f-de0d-43c9-94d5-04207ac048c6", "type": "subtopic", "title": "Experimentation and responsible AI", "children": [{"id": "8756065b-305f-4621-addb-02eac491582d", "type": "concept", "title": "A/B tests, quasi-experiments, cohorts, confounding, uplift, and practical significance"}, {"id": "55843453-a673-4a66-93e7-62385a02c992", "type": "concept", "title": "Prediction, classification, clustering, recommendations, generative AI, and process automation"}, {"id": "f583a495-6abe-4a54-b5c9-080be11f31b7", "type": "concept", "title": "Training data, hallucination, privacy, bias, explainability, security, model monitoring, and NIST AI RMF"}], "description": "Students distinguish correlation, prediction, and causation and learn when models require testing and human oversight."}]}, {"id": "2f8fec60-8b06-465b-8c5d-7265c224db07", "type": "topic", "title": "Payments, Finance, Controls, and Fraud", "description": "Hospitality systems handle money across desks, outlets, channels, currencies, and partners. This section links guest convenience to secure processing, accounting integrity, reconciliation, and loss prevention.", "children": [{"id": "d6264cbf-d3b6-46a4-99dd-92f79466dea3", "type": "subtopic", "title": "Payment lifecycle and architecture", "children": [{"id": "2efd1e88-797c-4b29-8e25-69fe6f05bd85", "type": "concept", "title": "Cards, wallets, account-to-account, cash, gift cards, loyalty, direct billing, and charge-to-room"}, {"id": "39d7c44b-90ac-4b54-b8f0-ff1dbe5914bb", "type": "concept", "title": "Gateway, processor, acquirer, issuer, token, terminal, merchant account, and payment service provider"}, {"id": "3ceaa779-b56a-4719-a564-c8d6ab398950", "type": "concept", "title": "Card-present, card-not-present, preauthorization, incremental authorization, tips, deposits, and refunds"}], "description": "Students trace authorization, capture, settlement, refund, and dispute across in-person and digital channels."}, {"id": "73a239d6-73fa-4137-b275-48dff977703c", "type": "subtopic", "title": "Accounting interfaces and reconciliation", "children": [{"id": "6526e177-6021-449d-a739-bdba62318de9", "type": "concept", "title": "Daily close, revenue posting, taxes, fees, tips, commissions, receivables, and deposits"}, {"id": "0ec3ed74-bddb-4ff6-817b-4b9bcc568af2", "type": "concept", "title": "PMS/POS subledgers, enterprise resource planning, general ledger, and bank feeds"}, {"id": "0ef8ebd5-e202-4655-b9fe-801cf72dd459", "type": "concept", "title": "Control totals, settlement files, timing differences, suspense, exceptions, and audit evidence"}], "description": "This subtopic ensures that operational activity can be proven against processor, bank, and ledger records."}, {"id": "b5d4dbda-72ae-4dbe-8dc6-c92b5b31baae", "type": "subtopic", "title": "Security, compliance, and fraud controls", "children": [{"id": "cf9fef63-e0c4-45b0-be9c-fc157cca7251", "type": "concept", "title": "PCI DSS scope, tokenization, point-to-point encryption, segmentation, and vendor responsibility"}, {"id": "f90a6d24-9f97-4552-8fa6-b40be06d1003", "type": "concept", "title": "Skimming, account testing, friendly fraud, chargebacks, refund abuse, loyalty fraud, and social engineering"}, {"id": "fd7dc3b1-48cc-4522-94f1-d661027c5d47", "type": "concept", "title": "Least privilege, dual control, limits, alerts, case management, incident escalation, and evidence preservation"}], "description": "Students learn risk-based practices for reducing payment exposure without claiming to replace qualified compliance or security specialists."}]}, {"id": "813f88ca-89e7-411f-8970-ab88124d81ed", "type": "topic", "title": "Cybersecurity, Privacy, Continuity, and Technology Risk", "description": "Hospitality is a high-contact, always-on environment with sensitive identity and payment data. Students learn to govern technology risk as an operational and guest-trust responsibility.", "children": [{"id": "5c4d627b-32bf-4197-9fbe-c15fcc8a0f56", "type": "subtopic", "title": "Cybersecurity risk management", "children": [{"id": "f635ea2d-0c40-435d-b407-bfa0d0332a36", "type": "concept", "title": "NIST CSF 2.0 functions: Govern, Identify, Protect, Detect, Respond, and Recover"}, {"id": "2d6b5240-df8e-4e56-8831-886026678f04", "type": "concept", "title": "Assets, threats, vulnerabilities, likelihood, impact, controls, residual risk, and risk acceptance"}, {"id": "61ab0457-2c32-4184-9053-34528019fda4", "type": "concept", "title": "Identity, multifactor authentication, least privilege, patching, secure configuration, logging, and awareness"}], "description": "Students apply a structured cycle to prioritize risks and communicate them in business terms."}, {"id": "4d5fcc1c-4ae5-42d6-8f8c-2f0db3b7ede7", "type": "subtopic", "title": "Privacy and data governance", "children": [{"id": "e1b53bd8-db4d-470e-a4c8-6f200790390f", "type": "concept", "title": "Collection, notice, consent, use, sharing, retention, access, correction, deletion, and disposal"}, {"id": "21f36d6a-8c33-41c8-a0c3-f48b0947f67c", "type": "concept", "title": "Sensitive data, children, biometrics, location, profiling, cross-border transfers, and data-subject rights"}, {"id": "cb7c8a19-9043-46ea-add2-f5ed99e9897e", "type": "concept", "title": "Privacy impact assessments, records of processing, vendor clauses, breach duties, and counsel referral"}], "description": "This subtopic treats privacy as a life-cycle discipline shaped by jurisdiction, purpose, guest expectations, and vendor relationships."}, {"id": "7019625d-74fe-4061-a078-be627a33f247", "type": "subtopic", "title": "Continuity and incident response", "children": [{"id": "2611eb57-076f-4d26-82a6-68b5202eba36", "type": "concept", "title": "Business impact analysis, recovery priorities, recovery time and recovery point objectives"}, {"id": "72da4667-ddf7-4e04-9c59-eb80db8d3a0d", "type": "concept", "title": "Manual operations, offline modes, backups, alternate communications, emergency access, and restoration"}, {"id": "64efdab1-cbd0-49e6-a95a-5e0dfb8e8712", "type": "concept", "title": "Incident roles, triage, containment, legal and insurer escalation, guest communications, lessons learned"}], "description": "Students prepare for system failure, cyber incidents, connectivity loss, and vendor outages while keeping essential service safe."}]}, {"id": "b077edb0-ce50-4307-bc04-1c4cc2039a6e", "type": "topic", "title": "Mobile, Contactless, IoT, and Inclusive Guest Experience", "description": "Digital convenience succeeds only when it is reliable, usable, accessible, secure, and supported by a human alternative. Students evaluate technology through the complete guest and employee journey.", "children": [{"id": "22383a67-f952-4eca-a917-3f321d4e311e", "type": "subtopic", "title": "Mobile and self-service journeys", "children": [{"id": "86a067f5-fc16-4562-87ad-719f50714571", "type": "concept", "title": "Mobile booking, check-in, identity verification, digital keys, messaging, ordering, payment, and checkout"}, {"id": "d4fccd62-4ee9-4be3-9564-da9df601fe85", "type": "concept", "title": "Kiosks, QR interactions, chat, virtual concierge, queue management, and wayfinding"}, {"id": "d1c5bae1-9a04-4e2a-a4eb-6fd8f83d17c0", "type": "concept", "title": "Failure recovery, assisted service, device compatibility, language, connectivity, and adoption"}], "description": "Students design digital touchpoints that reduce friction without transferring hidden work or risk to the guest."}, {"id": "b92545b1-c5e1-4913-b298-bb5ee83afb6f", "type": "subtopic", "title": "IoT, smart rooms, facilities, and energy", "children": [{"id": "e01bdb95-06e0-4281-a95f-dc6a1ab5fd16", "type": "concept", "title": "Locks, thermostats, lighting, occupancy, air quality, water, elevators, and building systems"}, {"id": "60d9b855-9c14-47c0-880a-13684557eb25", "type": "concept", "title": "Device identity, gateways, protocols, telemetry, remote management, firmware, and segmentation"}, {"id": "7f7169b4-8536-4173-8c2c-b558d92a516b", "type": "concept", "title": "Predictive maintenance, demand response, energy optimization, alerts, overrides, and commissioning"}], "description": "This subtopic connects sensors and controls to comfort, maintenance, safety, and environmental performance."}, {"id": "b88a7caa-e204-4c78-a857-b24fc3e03ddf", "type": "subtopic", "title": "Accessibility, inclusion, and service ethics", "children": [{"id": "8141bfc8-9136-46d7-95c4-5e4ec70e3ab0", "type": "concept", "title": "Perceivable, operable, understandable, and robust digital experiences"}, {"id": "87145f37-0c9c-471f-95ff-bfc1009260d1", "type": "concept", "title": "Captions, contrast, keyboard access, screen readers, plain language, accessible authentication, and testing"}, {"id": "8af1f755-cf52-4d66-af60-dd42de601c0a", "type": "concept", "title": "Cash and human alternatives, dignity, non-discrimination, consent, surveillance concerns, and service recovery"}], "description": "Students use inclusive design to make technology workable for diverse bodies, senses, languages, abilities, contexts, and levels of digital confidence."}]}, {"id": "ca8ac642-caf3-407f-aba9-ffb6b600c426", "type": "topic", "title": "Technology Selection, Vendor Management, and Business Cases", "description": "Choosing technology is a disciplined organizational decision. This section teaches students to translate needs into evidence, compare whole-life value, and negotiate accountable partnerships.", "children": [{"id": "c1c7d444-9bfd-45ef-991a-012bdc19c8a5", "type": "subtopic", "title": "Requirements and market discovery", "children": [{"id": "c34931a1-d732-4c96-967c-2f2de4f63ce6", "type": "concept", "title": "Stakeholders, personas, process maps, pain points, jobs to be done, and future-state design"}, {"id": "ce22baed-bb36-4f61-a1ef-7d08b4123a9a", "type": "concept", "title": "Functional, data, integration, security, privacy, accessibility, performance, support, and compliance requirements"}, {"id": "13ffcca3-6379-4271-a4b2-c0aeb6dc04ca", "type": "concept", "title": "Request for information, market scan, references, demonstrations, sandbox trials, and proof of concept"}], "description": "Students separate mandatory capabilities and constraints from attractive but low-value features."}, {"id": "4777d22e-9df3-4760-8143-894a0a02ede2", "type": "subtopic", "title": "Evaluation and business case", "children": [{"id": "24197aa9-f1c7-4443-ab77-ffe242d06ed4", "type": "concept", "title": "Weighted criteria, scripted demos, use cases, scoring anchors, fit-gap analysis, and bias controls"}, {"id": "35e6bd88-66c5-4ac2-bd67-90275db1ce92", "type": "concept", "title": "Acquisition, implementation, interfaces, hardware, training, support, upgrades, exit, and total cost"}, {"id": "ad2eb0d4-ad80-4628-b405-9abbfe7bebe3", "type": "concept", "title": "Benefits, baseline, sensitivity, risk-adjusted value, payback, governance, and benefits owner"}], "description": "This subtopic combines quantitative and qualitative evidence into a transparent recommendation."}, {"id": "ef5e9ebd-2a58-44c1-91b6-0fb2d9404639", "type": "subtopic", "title": "Contracts and vendor governance", "children": [{"id": "3fc43124-5205-4a8f-964e-900f99e2bb24", "type": "concept", "title": "Scope, deliverables, milestones, acceptance, fees, renewals, change control, and warranties"}, {"id": "0283d27b-3ace-4df1-bfe5-a0abf14f9b78", "type": "concept", "title": "Service levels, uptime, support, security, data processing, insurance, indemnity, audit, and breach notification"}, {"id": "10c3e2f8-fddd-4cd7-90a4-dbf8dc24d034", "type": "concept", "title": "Data portability, integration access, subcontractors, benchmarking, termination, transition assistance, and vendor lock-in"}], "description": "Students learn the commercial and operational terms that sustain performance after the sale."}]}, {"id": "ebd4e2d1-e96a-4833-8098-b15b86b78f41", "type": "topic", "title": "Implementation, Change Management, and Adoption", "description": "Even good technology fails when workflow, configuration, training, incentives, and support are misaligned. Students learn to plan implementation as an operating-model change.", "children": [{"id": "ea504436-812a-4c88-9fff-6cbeb7018e3b", "type": "subtopic", "title": "Implementation lifecycle", "children": [{"id": "c16a5ef1-a6b4-49c8-8560-ee9a7460dd20", "type": "concept", "title": "Charter, governance, scope, plan, budget, risks, issues, decisions, and change control"}, {"id": "57c81a5a-54d5-4590-9c72-485dba408458", "type": "concept", "title": "Configuration, interfaces, data migration, testing, training, cutover, rollback, and hypercare"}, {"id": "c845ab85-6c2a-4e51-b8fa-5e3389e552fc", "type": "concept", "title": "Waterfall, agile, pilot, phased, parallel, and big-bang approaches"}], "description": "Students organize discovery through stabilization using explicit gates, ownership, evidence, and risk controls."}, {"id": "554a1f24-7794-408e-b3e0-86cd51baa886", "type": "subtopic", "title": "Data migration, testing, and readiness", "children": [{"id": "d79886ef-e369-47c8-a0a2-391afd5944c3", "type": "concept", "title": "Extract, cleanse, map, transform, load, reconcile, archive, and retention"}, {"id": "71965695-a289-40ec-8b9f-4eb7dbed1af1", "type": "concept", "title": "Unit, integration, end-to-end, security, performance, accessibility, recovery, and user acceptance tests"}, {"id": "9613d592-0013-4e0c-9b8a-c7f92ec4b24c", "type": "concept", "title": "Go-live criteria, defect severity, rehearsals, contingency, readiness dashboard, and sign-off"}], "description": "This subtopic protects operations by proving data, workflows, controls, and support before launch."}, {"id": "bdfe742a-4206-45b6-99c2-2facbabd907a", "type": "subtopic", "title": "Change, learning, and benefits realization", "children": [{"id": "94a671e8-21ca-4a9e-a9aa-eb0257af712e", "type": "concept", "title": "Stakeholder impact, sponsors, champions, resistance, communications, feedback, and psychological safety"}, {"id": "c5db00e6-e5c6-41d3-977b-9d7caafe00c9", "type": "concept", "title": "Role-based learning, practice environment, job aids, coaching, proficiency, and support model"}, {"id": "b15a5a76-3b75-4714-8f34-fc383b62ec43", "type": "concept", "title": "Adoption measures, process compliance, benefit measures, post-implementation review, and continuous improvement"}], "description": "Students plan for behavior, capability, and ownership—not just system availability."}]}, {"id": "aba95729-c16d-4aa9-a6b4-0074a93b63df", "type": "topic", "title": "Innovation, Responsible Technology, and the Future of Hospitality", "description": "The final section helps students investigate emerging technology without hype. They learn to test strategic relevance, operational feasibility, stakeholder impacts, and ethical boundaries.", "children": [{"id": "506f984c-6ead-4dea-ba46-0378b742c5fc", "type": "subtopic", "title": "Technology sensing and scenario analysis", "children": [{"id": "30ba81a2-f7bf-470f-a919-7d5db06b68a5", "type": "concept", "title": "AI agents, robotics, biometrics, spatial computing, digital identity, autonomous operations, and new platforms"}, {"id": "456efb80-9624-4656-b201-e0a5d44ed9c3", "type": "concept", "title": "Horizon scanning, trend evidence, maturity, diffusion, dependencies, and uncertainty"}, {"id": "82dbb206-fad9-4563-9a6d-2002b0917ff9", "type": "concept", "title": "Scenarios, signposts, options, experiments, stop criteria, and portfolio balance"}], "description": "Students build a repeatable process for recognizing signals and examining plausible futures."}, {"id": "994de3c3-fa0d-4661-a16f-2ec6f5a65a4c", "type": "subtopic", "title": "Responsible innovation", "children": [{"id": "615aaa9c-0928-4cec-bc40-7eda893c0930", "type": "concept", "title": "Guest and employee participation, accessibility, labor impacts, deskilling, and power"}, {"id": "44c42878-560b-4901-ba96-1d9673ee2e44", "type": "concept", "title": "Privacy, bias, security, safety, explainability, contestability, and human oversight"}, {"id": "bca3a2d3-b35d-4b0b-8a8b-3a09e8a41d5a", "type": "concept", "title": "Responsible AI governance, impact assessment, red teams, monitoring, appeals, and retirement"}], "description": "This subtopic makes values, affected groups, and potential harms part of the design decision."}, {"id": "b55946c6-a839-4cde-bc95-0fcf93af1a36", "type": "subtopic", "title": "Sustainability and shared value", "children": [{"id": "dc8d69b2-1e5b-4bbe-9de1-7ab28b122da6", "type": "concept", "title": "Energy, water, waste, carbon, travel, procurement, and behavior-change applications"}, {"id": "8c5cba5c-471c-4aff-add7-0c6a277882c8", "type": "concept", "title": "Hardware life cycle, e-waste, cloud and AI energy use, repairability, and supplier practices"}, {"id": "2d9d15da-2589-485b-bc4e-ea6715b8060c", "type": "concept", "title": "Baseline, materiality, rebound effects, green claims, assurance, stakeholder value, and transparent reporting"}], "description": "Students evaluate whether technology improves environmental and social outcomes across its full life cycle."}]}], "dbBacked": true}$hisyjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'hospitality-information-systems'
);

update public.learning_paths
set
  title = 'Hospitality Information Systems',
  goal = 'Hospitality Information Systems',
  summary = 'This course prepares hospitality managers to select, govern, implement, use, integrate, and improve information systems across lodging, foodservice, commercial, guest-experience, and enterprise operations. Students investigate PMS, POS, CRS and distribution, CRM and loyalty, RMS, payments, data and APIs, analytics and AI, mobile and IoT experiences, cybersecurity and privacy, vendor management, and organizational change. The emphasis is managerial fluency: mapping workflows, interpreting system data, evaluating controls and tradeoffs, designing inclusive service, questioning automated recommendations, and building an evidence-based technology roadmap.',
  data = $hisyjson${"slug": "hospitality-information-systems", "title": "Hospitality Information Systems", "description": "This course prepares hospitality managers to select, govern, implement, use, integrate, and improve information systems across lodging, foodservice, commercial, guest-experience, and enterprise operations. Students investigate PMS, POS, CRS and distribution, CRM and loyalty, RMS, payments, data and APIs, analytics and AI, mobile and IoT experiences, cybersecurity and privacy, vendor management, and organizational change. The emphasis is managerial fluency: mapping workflows, interpreting system data, evaluating controls and tradeoffs, designing inclusive service, questioning automated recommendations, and building an evidence-based technology roadmap.", "topics": [{"id": "7ccc3537-d317-4dc5-bb86-8896b5f3b540", "type": "topic", "title": "Hospitality Digital Ecosystem and Systems Thinking", "description": "Hospitality technology is a connected service system, not a collection of isolated applications. This section gives students a managerial map of how people, processes, data, devices, vendors, and platforms combine to deliver the guest experience and business performance.", "children": [{"id": "b4274d5b-e2a3-44f5-84d9-fa1fd3d6ac36", "type": "subtopic", "title": "Enterprise and property technology landscape", "children": [{"id": "3c9b83a5-1fd4-41c1-bb1f-4e6711f477ef", "type": "concept", "title": "Guest-facing, operational, commercial, financial, workforce, facilities, and enterprise systems"}, {"id": "07f286f2-c4c2-452e-933f-2168fba1b4e2", "type": "concept", "title": "Property, cluster, brand, owner, franchise, management-company, and third-party perspectives"}, {"id": "cdb84a67-4950-4428-b610-c49dec3aa058", "type": "concept", "title": "Cloud, on-premises, edge, mobile, software-as-a-service, and platform models"}], "description": "Students learn the major layers of a hotel, resort, restaurant, and multi-property technology stack so they can locate a problem before proposing a tool."}, {"id": "0392e43a-3a93-457d-b9b8-927f2000876f", "type": "subtopic", "title": "Systems thinking and service processes", "children": [{"id": "d5bb19d1-3a75-407f-9d0d-bdfc43184f72", "type": "concept", "title": "Inputs, activities, handoffs, controls, outputs, outcomes, and feedback loops"}, {"id": "5ab480d9-82f4-4750-b8fa-73fb28f5b5cf", "type": "concept", "title": "Service blueprinting across frontstage, backstage, and support processes"}, {"id": "7819dc98-22ed-4803-b0fd-3f55e4ea50bf", "type": "concept", "title": "Bottlenecks, failure demand, workarounds, automation opportunities, and unintended consequences"}], "description": "This subtopic connects technology choices to the end-to-end work that creates value for guests and employees."}, {"id": "7d8b4eb9-e616-4180-a721-32f92b8ddc21", "type": "subtopic", "title": "Technology strategy and value", "children": [{"id": "ac45e3f6-b246-4421-9561-bcfa7ea5bbd2", "type": "concept", "title": "Strategic alignment, differentiation, standardization, scalability, and operating-model fit"}, {"id": "1b167c4c-40a5-452a-86a7-533c51a8420a", "type": "concept", "title": "Revenue, cost, productivity, quality, risk, resilience, accessibility, and sustainability value"}, {"id": "8eea02ff-455f-4905-9d33-2d0bc42dd613", "type": "concept", "title": "Total cost of ownership, opportunity cost, benefits realization, and technical debt"}], "description": "Students frame technology as an investment in capabilities and outcomes rather than as a feature checklist."}]}, {"id": "7359a7fe-7339-43ac-b2d7-be24bd43f73d", "type": "topic", "title": "Property Management Systems and Lodging Operations", "description": "The property management system is the operational hub of lodging. Students learn the guest-account and room-inventory logic behind the screens so they can design controls, diagnose exceptions, and improve service.", "children": [{"id": "072bd533-baa7-4a6c-943c-11ca07bb87dd", "type": "subtopic", "title": "Reservation-to-departure workflow", "children": [{"id": "4d2f8d19-e72c-4832-990b-fa9cdd0a396e", "type": "concept", "title": "Availability search, reservation, guarantee, deposit, modification, cancellation, and no-show"}, {"id": "eac885e4-8516-46ca-b02d-28b8336e75dc", "type": "concept", "title": "Pre-arrival, registration, room assignment, keys, check-in, stay changes, and check-out"}, {"id": "f91792d7-8554-47ce-96c5-8e5ece89b9ad", "type": "concept", "title": "Walks, overbooking, room moves, split stays, extensions, early departures, and service recovery"}], "description": "Students trace the guest record and stay through its full life cycle, including the exceptions that expose weak processes."}, {"id": "ab2d6d58-10bd-408f-8fee-af8e41b24522", "type": "subtopic", "title": "Rooms, rates, folios, and night audit", "children": [{"id": "b68f26b1-8f6d-45b2-90c7-cd98eaae3ba3", "type": "concept", "title": "Room types, room status, housekeeping, out-of-order, and maintenance coordination"}, {"id": "d826a910-cb3a-4728-bd5e-864417848432", "type": "concept", "title": "Rate plans, packages, restrictions, routing, allowances, taxes, fees, and folio windows"}, {"id": "18ce4e3d-6ddb-44f5-a48d-f60346991f3b", "type": "concept", "title": "Night audit, business date, interface reconciliation, exception reports, and audit trail"}], "description": "This subtopic explains the operational data structures that support inventory control, posting, settlement, and daily close."}, {"id": "d39585db-9a2d-4ed8-b515-fd2a1c3025cb", "type": "subtopic", "title": "Multi-property and stakeholder controls", "children": [{"id": "e537a5c1-189b-43ba-9bdb-7a57c81df55b", "type": "concept", "title": "Chain codes, property configuration, user roles, approvals, and segregation of duties"}, {"id": "f116aa41-2747-4d76-9871-1a5fd20887fd", "type": "concept", "title": "Profiles, negotiated rates, group blocks, allotments, and central services"}, {"id": "e2e3cdc9-7cc6-442e-aa17-96dd4fbdd7e0", "type": "concept", "title": "Standard operating procedures, data ownership, support tiers, and property-level autonomy"}], "description": "Students examine how PMS configuration and access differ across ownership, brand, management, and regional structures."}]}, {"id": "fb17a2e3-4c39-4216-9077-073c2e9f4284", "type": "topic", "title": "Point-of-Sale, Foodservice, Inventory, and Procurement Systems", "description": "Food-and-beverage systems join guest service with production, inventory, labor, payments, and accounting. This section prepares students to evaluate both front-of-house speed and back-of-house control.", "children": [{"id": "cfbd1139-fa59-4797-975b-6a4d855e02e9", "type": "subtopic", "title": "POS transaction and service design", "children": [{"id": "eab00706-b407-4adb-8a89-20c7b5a334fc", "type": "concept", "title": "Menu hierarchy, modifiers, pricing, discounts, comps, voids, tips, and taxes"}, {"id": "14fe8444-7c3f-4285-b59c-9e549ae180cc", "type": "concept", "title": "Table service, quick service, bars, banquets, kiosks, mobile ordering, and delivery"}, {"id": "eefcff55-9b86-46fb-9d33-cc29321d9147", "type": "concept", "title": "Kitchen display, printers, coursing, checks, split tender, offline mode, and closeout"}], "description": "Students connect menu design and service style to ordering, routing, fulfillment, payment, and recovery workflows."}, {"id": "75882426-308d-4160-a986-1d1d9769ed05", "type": "subtopic", "title": "Inventory, recipe, and cost control", "children": [{"id": "e8d5b76d-5cb2-463e-9fd5-c72d15800869", "type": "concept", "title": "Recipes, yields, portions, theoretical versus actual usage, and menu engineering"}, {"id": "c303ceeb-b9a9-4a00-a228-4a662bc44216", "type": "concept", "title": "Purchasing, receiving, transfers, counts, waste, spoilage, and variance"}, {"id": "65546de2-a05d-449d-a182-75cca547c0a8", "type": "concept", "title": "Reorder points, par levels, vendor catalogs, traceability, and food-safety records"}], "description": "This subtopic uses systems data to protect margin, availability, quality, and traceability."}, {"id": "5dc9966e-7679-46b5-b5fc-bbb8729d3dec", "type": "subtopic", "title": "Labor, procurement, and accounting integration", "children": [{"id": "0b85a9bb-bc6e-4edf-917c-9735ae0de719", "type": "concept", "title": "Demand-based scheduling, timekeeping, payroll interfaces, and labor productivity"}, {"id": "15178cae-55c0-489b-a124-193c4f8888e3", "type": "concept", "title": "Requisitions, purchase orders, approvals, invoices, three-way match, and e-procurement"}, {"id": "1d3a59bf-11f2-4710-ad95-b568902a70c5", "type": "concept", "title": "Revenue centers, tenders, taxes, tips, charge-to-room, and general-ledger mapping"}], "description": "Students learn how operational transactions become schedules, liabilities, journal entries, and management reports."}]}, {"id": "b05b5755-cfeb-445a-84bb-e843e9c6d371", "type": "topic", "title": "Reservations, Distribution, and Digital Commerce", "description": "A room or table may be sold through many intermediaries. Students learn how availability, rates, content, identity, and economics move across the distribution network—and where errors or conflicts arise.", "children": [{"id": "6031eeee-2422-4f84-8453-45ea4cd9fc84", "type": "subtopic", "title": "CRS, booking engine, GDS, and channel architecture", "children": [{"id": "61bf6a8b-c78c-4965-9873-7ecf55869e32", "type": "concept", "title": "Central reservation system, internet booking engine, call center, and property inventory"}, {"id": "47be1b4f-eac4-4f56-81a1-3940fb645e8f", "type": "concept", "title": "Global distribution systems, online travel agencies, wholesalers, bedbanks, and tour operators"}, {"id": "a3c98550-c7eb-435f-824a-bc1e992552a0", "type": "concept", "title": "Channel managers, switches, metasearch, super apps, and connectivity providers"}], "description": "Students map the systems and messages that connect inventory to direct and indirect demand."}, {"id": "380051f0-59b7-4d1a-8a49-d630ea114f3c", "type": "subtopic", "title": "Content, rate, and inventory synchronization", "children": [{"id": "ee411603-5751-4a4e-b994-0f0d59e600df", "type": "concept", "title": "Room and rate mapping, descriptions, images, policies, amenities, and accessibility attributes"}, {"id": "6e1c8d4c-2ffe-4172-b5af-142ae3a36b25", "type": "concept", "title": "Availability, rates, inventory, restrictions, promotions, and stop-sell messages"}, {"id": "e3e80dd5-dfb7-421d-ad96-1091d6825c07", "type": "concept", "title": "Latency, oversell, stale content, parity, caching, reconciliation, and exception monitoring"}], "description": "This subtopic focuses on accurate, timely distribution of products and restrictions across channels."}, {"id": "c132fa84-1471-4356-a58f-c74ad1e81875", "type": "subtopic", "title": "Distribution economics and control", "children": [{"id": "00f186a7-97f8-4632-9eb7-38696501dade", "type": "concept", "title": "Direct versus intermediary economics, net rates, commissions, merchant and agency models"}, {"id": "1f85f800-ba0f-4ce4-98ca-71d3691aa2d9", "type": "concept", "title": "Attribution, conversion, cancellation, no-show, refund, chargeback, and lifetime value"}, {"id": "754cb56c-e69c-451a-8e28-42845999f657", "type": "concept", "title": "Channel mix, parity rules, loyalty/member rates, governance, and ethical consumer disclosure"}], "description": "Students compare reach and conversion with commissions, acquisition costs, data access, and dependency risk."}]}, {"id": "291fdb66-5d2f-496d-ae70-dbfe03ffb0c7", "type": "topic", "title": "Guest Data, CRM, Loyalty, and Personalization", "description": "Guest relationships depend on trustworthy identity, permission, and context. This section teaches students to create relevant experiences without turning personalization into surveillance or discrimination.", "children": [{"id": "2bea998e-a831-4063-ba11-476d71fa192c", "type": "subtopic", "title": "Guest identity and profile management", "children": [{"id": "45c439f2-df03-4b3f-853e-51391d19aa67", "type": "concept", "title": "Identifiers, duplicates, household and company relationships, preferences, and consent"}, {"id": "43143bab-fdcc-4b08-8b4e-6d05e5b4fb5a", "type": "concept", "title": "PMS profiles, CRM, customer data platforms, loyalty databases, and identity resolution"}, {"id": "db136b47-0655-412d-b07e-57ad8cafc45f", "type": "concept", "title": "Golden records, match rules, survivorship, provenance, data quality, and deletion"}], "description": "Students learn how profiles are created, matched, merged, enriched, and governed across stays and channels."}, {"id": "56820edb-3fec-4221-836d-3ba9d46b1894", "type": "subtopic", "title": "CRM and loyalty operations", "children": [{"id": "031630b7-bdc6-4667-9bd6-ed488c4e7306", "type": "concept", "title": "Segmentation, lifecycle journeys, campaigns, cases, tasks, and service recovery"}, {"id": "36a34323-8e85-4a96-a8db-7b69fb8f7be1", "type": "concept", "title": "Enrollment, tiers, earn and burn, benefits, partnerships, liability, and fraud"}, {"id": "17d4cedb-3938-4e32-99fa-d2bedc74075a", "type": "concept", "title": "Engagement, repeat behavior, churn, redemption, incremental value, and program economics"}], "description": "This subtopic connects guest data to acquisition, service, retention, recovery, and relationship value."}, {"id": "59885c21-9fd3-4e80-b4b0-3acfa48a75e1", "type": "subtopic", "title": "Responsible personalization", "children": [{"id": "40ed6ddf-66e8-412f-a89d-7de2c9fa6e3d", "type": "concept", "title": "Next-best action, recommendations, preference fulfillment, and human override"}, {"id": "bff67d89-32b7-4a99-894f-6531e95e8496", "type": "concept", "title": "Consent, transparency, data minimization, purpose limitation, and sensitive attributes"}, {"id": "a69b23e9-a0db-41af-90a8-61bc0dbcce08", "type": "concept", "title": "Bias testing, exclusion, vulnerable guests, accessibility, complaint handling, and opt-out"}], "description": "Students design relevant offers and service prompts while respecting choice, fairness, dignity, and context."}]}, {"id": "d11312ca-323c-48f3-aa11-aebd8d2c0da7", "type": "topic", "title": "Revenue Management Systems and Commercial Decision Support", "description": "Revenue systems turn demand signals, capacity, price, and controls into commercial recommendations. Students learn both the analytical logic and the managerial responsibility to challenge outputs.", "children": [{"id": "90b6ed11-5921-4062-b929-3b7c1214adba", "type": "subtopic", "title": "Forecasting and demand signals", "children": [{"id": "86c50f45-4698-4f0d-b02f-cf009528d6b0", "type": "concept", "title": "Bookings, pace, pickup, cancellations, no-shows, length of stay, and lead time"}, {"id": "eff7f3f6-7a49-4d92-8cff-65860acab94e", "type": "concept", "title": "Events, holidays, competitors, search, web traffic, weather, and market intelligence"}, {"id": "a3795385-ce0f-4180-bf66-b975fff4e14c", "type": "concept", "title": "Forecast horizon, granularity, seasonality, outliers, scenario ranges, and forecast error"}], "description": "Students examine how systems estimate unconstrained demand and uncertainty from internal and external evidence."}, {"id": "c65a7bdc-19c7-4d48-a9ef-edcc2cca2833", "type": "subtopic", "title": "Optimization, pricing, and inventory controls", "children": [{"id": "649c23fc-384b-4f48-9f5b-f63e35013ba5", "type": "concept", "title": "Segments, willingness to pay, price sensitivity, rate fences, and dynamic pricing"}, {"id": "518a972e-9bd4-47fe-aaad-9ecd8ea9682a", "type": "concept", "title": "Overbooking, minimum stay, closed-to-arrival, nested inventory, and displacement"}, {"id": "3c5b1528-208a-4a57-ae13-8e41683bca0d", "type": "concept", "title": "Group evaluation, bid price, upgrades, ancillary revenue, and total revenue management"}], "description": "This subtopic explains how RMS recommendations influence price, availability, and acceptance decisions."}, {"id": "df09010e-00e3-4874-861e-4f14f9e5088d", "type": "subtopic", "title": "Governance and performance", "children": [{"id": "2abd8c96-8338-4f54-ac77-d48fa1a1ed3d", "type": "concept", "title": "ADR, occupancy, RevPAR, TRevPAR, GOPPAR, contribution, and channel cost"}, {"id": "7c954d21-9ccf-4103-b635-7e5905b54461", "type": "concept", "title": "Overrides, reason codes, alerts, thresholds, approval rights, and revenue meetings"}, {"id": "036ddb31-a016-4344-b1a7-1379d4fc760b", "type": "concept", "title": "Model drift, feedback loops, price fairness, collusion risk, explainability, and human accountability"}], "description": "Students learn to monitor model outputs and commercial outcomes rather than treating automation as unquestionable authority."}]}, {"id": "6afa374e-142c-4d24-9570-9e54debf3ce3", "type": "topic", "title": "Data Architecture, Integration, APIs, and Interoperability", "description": "Reliable hospitality operations depend on systems exchanging consistent data at the right time. This section gives managers enough technical fluency to specify integrations, recognize failure modes, and ask better questions.", "children": [{"id": "2a329080-22a7-4f68-bcb5-0983ab852830", "type": "subtopic", "title": "Data models and master data", "children": [{"id": "b9a621a1-24fc-4c17-a12c-ec71eeaf6728", "type": "concept", "title": "Guests, reservations, stays, rooms, rates, outlets, products, employees, vendors, and transactions"}, {"id": "82a09422-2db9-4fdc-bedc-98853eac3900", "type": "concept", "title": "Master, reference, transactional, event, document, and analytical data"}, {"id": "4a98cde4-b274-464e-97a7-dd7a8772ddd8", "type": "concept", "title": "Data dictionary, metadata, ownership, lineage, retention, quality rules, and stewardship"}], "description": "Students learn why shared definitions and identifiers are prerequisites for trustworthy transactions and analytics."}, {"id": "838c702e-af8b-4277-8b09-a8cd5be6b22d", "type": "subtopic", "title": "Integration patterns and APIs", "children": [{"id": "2ad90e1e-17c9-4cb1-8ad6-e61ea8e4f071", "type": "concept", "title": "Files, batches, queues, webhooks, application programming interfaces, and event streams"}, {"id": "2d57d500-36be-4870-9fd8-04cd03be2540", "type": "concept", "title": "Requests, responses, authentication, schemas, mappings, validation, retries, and idempotency"}, {"id": "2c5645a9-6827-4604-9194-ae2cf84f2d28", "type": "concept", "title": "Point-to-point, middleware, integration platforms, microservices, and vendor marketplaces"}], "description": "This subtopic introduces the main ways systems communicate and the tradeoffs among speed, reliability, and complexity."}, {"id": "760427d8-5db4-4bbc-ad38-c088487f7de4", "type": "subtopic", "title": "Interoperability and operational resilience", "children": [{"id": "0ef63b22-8787-4b39-9dbf-589b7fe1c5c1", "type": "concept", "title": "Hospitality standards and shared schemas from HTNG and OpenTravel communities"}, {"id": "9bd5af0a-ee6f-4a8b-b04d-16601e15aa3c", "type": "concept", "title": "Latency, duplication, ordering, partial failure, reconciliation, observability, and audit logs"}, {"id": "04682a5c-c000-4389-83bb-99f5edda6956", "type": "concept", "title": "Sandbox, test cases, cutover, rollback, offline procedures, service levels, and support ownership"}], "description": "Students test integrations as business processes, including exceptions and recovery—not merely as successful message transfers."}]}, {"id": "d8cbe598-154e-448f-9d23-796618c1b3a5", "type": "topic", "title": "Analytics, Business Intelligence, Experimentation, and AI", "description": "Hospitality data becomes valuable only when it improves a decision. Students learn to frame questions, build defensible metrics, interpret evidence, and use automation with appropriate skepticism.", "children": [{"id": "49643b59-47cf-47ae-a49e-dd84493dc373", "type": "subtopic", "title": "Metrics and semantic consistency", "children": [{"id": "6e5d6652-1e90-4420-8795-122a39b45cd1", "type": "concept", "title": "Operational, guest, commercial, financial, workforce, sustainability, and risk measures"}, {"id": "7aa7f76a-bbe3-4de1-8ba6-6c7e0f5407fc", "type": "concept", "title": "Dimensions, grain, numerator, denominator, time window, filters, targets, and benchmarks"}, {"id": "b29c7f08-4fb2-423d-8822-d17920ce620d", "type": "concept", "title": "Occupancy, ADR, RevPAR, table turns, check average, labor cost, conversion, and satisfaction"}], "description": "Students define performance measures so teams do not make decisions from conflicting versions of the truth."}, {"id": "50bc2d2a-30f1-477f-aa3d-f42ee6754ba1", "type": "subtopic", "title": "Dashboards and decision workflows", "children": [{"id": "29e505ff-992f-4481-88b0-b3948fd27884", "type": "concept", "title": "Executive, departmental, real-time, exception, diagnostic, and self-service views"}, {"id": "055283f0-b7a3-4a11-bd59-0b71ff788aa7", "type": "concept", "title": "Visual hierarchy, thresholds, alerts, drill-down, annotations, accessibility, and mobile use"}, {"id": "0334eb31-bbe9-4912-a7d0-52b415fea63e", "type": "concept", "title": "Decision cadence, meeting routines, owners, actions, due dates, and outcome tracking"}], "description": "This subtopic turns displays into tools for attention, diagnosis, action, ownership, and follow-through."}, {"id": "5f1a127f-de0d-43c9-94d5-04207ac048c6", "type": "subtopic", "title": "Experimentation and responsible AI", "children": [{"id": "8756065b-305f-4621-addb-02eac491582d", "type": "concept", "title": "A/B tests, quasi-experiments, cohorts, confounding, uplift, and practical significance"}, {"id": "55843453-a673-4a66-93e7-62385a02c992", "type": "concept", "title": "Prediction, classification, clustering, recommendations, generative AI, and process automation"}, {"id": "f583a495-6abe-4a54-b5c9-080be11f31b7", "type": "concept", "title": "Training data, hallucination, privacy, bias, explainability, security, model monitoring, and NIST AI RMF"}], "description": "Students distinguish correlation, prediction, and causation and learn when models require testing and human oversight."}]}, {"id": "2f8fec60-8b06-465b-8c5d-7265c224db07", "type": "topic", "title": "Payments, Finance, Controls, and Fraud", "description": "Hospitality systems handle money across desks, outlets, channels, currencies, and partners. This section links guest convenience to secure processing, accounting integrity, reconciliation, and loss prevention.", "children": [{"id": "d6264cbf-d3b6-46a4-99dd-92f79466dea3", "type": "subtopic", "title": "Payment lifecycle and architecture", "children": [{"id": "2efd1e88-797c-4b29-8e25-69fe6f05bd85", "type": "concept", "title": "Cards, wallets, account-to-account, cash, gift cards, loyalty, direct billing, and charge-to-room"}, {"id": "39d7c44b-90ac-4b54-b8f0-ff1dbe5914bb", "type": "concept", "title": "Gateway, processor, acquirer, issuer, token, terminal, merchant account, and payment service provider"}, {"id": "3ceaa779-b56a-4719-a564-c8d6ab398950", "type": "concept", "title": "Card-present, card-not-present, preauthorization, incremental authorization, tips, deposits, and refunds"}], "description": "Students trace authorization, capture, settlement, refund, and dispute across in-person and digital channels."}, {"id": "73a239d6-73fa-4137-b275-48dff977703c", "type": "subtopic", "title": "Accounting interfaces and reconciliation", "children": [{"id": "6526e177-6021-449d-a739-bdba62318de9", "type": "concept", "title": "Daily close, revenue posting, taxes, fees, tips, commissions, receivables, and deposits"}, {"id": "0ec3ed74-bddb-4ff6-817b-4b9bcc568af2", "type": "concept", "title": "PMS/POS subledgers, enterprise resource planning, general ledger, and bank feeds"}, {"id": "0ef8ebd5-e202-4655-b9fe-801cf72dd459", "type": "concept", "title": "Control totals, settlement files, timing differences, suspense, exceptions, and audit evidence"}], "description": "This subtopic ensures that operational activity can be proven against processor, bank, and ledger records."}, {"id": "b5d4dbda-72ae-4dbe-8dc6-c92b5b31baae", "type": "subtopic", "title": "Security, compliance, and fraud controls", "children": [{"id": "cf9fef63-e0c4-45b0-be9c-fc157cca7251", "type": "concept", "title": "PCI DSS scope, tokenization, point-to-point encryption, segmentation, and vendor responsibility"}, {"id": "f90a6d24-9f97-4552-8fa6-b40be06d1003", "type": "concept", "title": "Skimming, account testing, friendly fraud, chargebacks, refund abuse, loyalty fraud, and social engineering"}, {"id": "fd7dc3b1-48cc-4522-94f1-d661027c5d47", "type": "concept", "title": "Least privilege, dual control, limits, alerts, case management, incident escalation, and evidence preservation"}], "description": "Students learn risk-based practices for reducing payment exposure without claiming to replace qualified compliance or security specialists."}]}, {"id": "813f88ca-89e7-411f-8970-ab88124d81ed", "type": "topic", "title": "Cybersecurity, Privacy, Continuity, and Technology Risk", "description": "Hospitality is a high-contact, always-on environment with sensitive identity and payment data. Students learn to govern technology risk as an operational and guest-trust responsibility.", "children": [{"id": "5c4d627b-32bf-4197-9fbe-c15fcc8a0f56", "type": "subtopic", "title": "Cybersecurity risk management", "children": [{"id": "f635ea2d-0c40-435d-b407-bfa0d0332a36", "type": "concept", "title": "NIST CSF 2.0 functions: Govern, Identify, Protect, Detect, Respond, and Recover"}, {"id": "2d6b5240-df8e-4e56-8831-886026678f04", "type": "concept", "title": "Assets, threats, vulnerabilities, likelihood, impact, controls, residual risk, and risk acceptance"}, {"id": "61ab0457-2c32-4184-9053-34528019fda4", "type": "concept", "title": "Identity, multifactor authentication, least privilege, patching, secure configuration, logging, and awareness"}], "description": "Students apply a structured cycle to prioritize risks and communicate them in business terms."}, {"id": "4d5fcc1c-4ae5-42d6-8f8c-2f0db3b7ede7", "type": "subtopic", "title": "Privacy and data governance", "children": [{"id": "e1b53bd8-db4d-470e-a4c8-6f200790390f", "type": "concept", "title": "Collection, notice, consent, use, sharing, retention, access, correction, deletion, and disposal"}, {"id": "21f36d6a-8c33-41c8-a0c3-f48b0947f67c", "type": "concept", "title": "Sensitive data, children, biometrics, location, profiling, cross-border transfers, and data-subject rights"}, {"id": "cb7c8a19-9043-46ea-add2-f5ed99e9897e", "type": "concept", "title": "Privacy impact assessments, records of processing, vendor clauses, breach duties, and counsel referral"}], "description": "This subtopic treats privacy as a life-cycle discipline shaped by jurisdiction, purpose, guest expectations, and vendor relationships."}, {"id": "7019625d-74fe-4061-a078-be627a33f247", "type": "subtopic", "title": "Continuity and incident response", "children": [{"id": "2611eb57-076f-4d26-82a6-68b5202eba36", "type": "concept", "title": "Business impact analysis, recovery priorities, recovery time and recovery point objectives"}, {"id": "72da4667-ddf7-4e04-9c59-eb80db8d3a0d", "type": "concept", "title": "Manual operations, offline modes, backups, alternate communications, emergency access, and restoration"}, {"id": "64efdab1-cbd0-49e6-a95a-5e0dfb8e8712", "type": "concept", "title": "Incident roles, triage, containment, legal and insurer escalation, guest communications, lessons learned"}], "description": "Students prepare for system failure, cyber incidents, connectivity loss, and vendor outages while keeping essential service safe."}]}, {"id": "b077edb0-ce50-4307-bc04-1c4cc2039a6e", "type": "topic", "title": "Mobile, Contactless, IoT, and Inclusive Guest Experience", "description": "Digital convenience succeeds only when it is reliable, usable, accessible, secure, and supported by a human alternative. Students evaluate technology through the complete guest and employee journey.", "children": [{"id": "22383a67-f952-4eca-a917-3f321d4e311e", "type": "subtopic", "title": "Mobile and self-service journeys", "children": [{"id": "86a067f5-fc16-4562-87ad-719f50714571", "type": "concept", "title": "Mobile booking, check-in, identity verification, digital keys, messaging, ordering, payment, and checkout"}, {"id": "d4fccd62-4ee9-4be3-9564-da9df601fe85", "type": "concept", "title": "Kiosks, QR interactions, chat, virtual concierge, queue management, and wayfinding"}, {"id": "d1c5bae1-9a04-4e2a-a4eb-6fd8f83d17c0", "type": "concept", "title": "Failure recovery, assisted service, device compatibility, language, connectivity, and adoption"}], "description": "Students design digital touchpoints that reduce friction without transferring hidden work or risk to the guest."}, {"id": "b92545b1-c5e1-4913-b298-bb5ee83afb6f", "type": "subtopic", "title": "IoT, smart rooms, facilities, and energy", "children": [{"id": "e01bdb95-06e0-4281-a95f-dc6a1ab5fd16", "type": "concept", "title": "Locks, thermostats, lighting, occupancy, air quality, water, elevators, and building systems"}, {"id": "60d9b855-9c14-47c0-880a-13684557eb25", "type": "concept", "title": "Device identity, gateways, protocols, telemetry, remote management, firmware, and segmentation"}, {"id": "7f7169b4-8536-4173-8c2c-b558d92a516b", "type": "concept", "title": "Predictive maintenance, demand response, energy optimization, alerts, overrides, and commissioning"}], "description": "This subtopic connects sensors and controls to comfort, maintenance, safety, and environmental performance."}, {"id": "b88a7caa-e204-4c78-a857-b24fc3e03ddf", "type": "subtopic", "title": "Accessibility, inclusion, and service ethics", "children": [{"id": "8141bfc8-9136-46d7-95c4-5e4ec70e3ab0", "type": "concept", "title": "Perceivable, operable, understandable, and robust digital experiences"}, {"id": "87145f37-0c9c-471f-95ff-bfc1009260d1", "type": "concept", "title": "Captions, contrast, keyboard access, screen readers, plain language, accessible authentication, and testing"}, {"id": "8af1f755-cf52-4d66-af60-dd42de601c0a", "type": "concept", "title": "Cash and human alternatives, dignity, non-discrimination, consent, surveillance concerns, and service recovery"}], "description": "Students use inclusive design to make technology workable for diverse bodies, senses, languages, abilities, contexts, and levels of digital confidence."}]}, {"id": "ca8ac642-caf3-407f-aba9-ffb6b600c426", "type": "topic", "title": "Technology Selection, Vendor Management, and Business Cases", "description": "Choosing technology is a disciplined organizational decision. This section teaches students to translate needs into evidence, compare whole-life value, and negotiate accountable partnerships.", "children": [{"id": "c1c7d444-9bfd-45ef-991a-012bdc19c8a5", "type": "subtopic", "title": "Requirements and market discovery", "children": [{"id": "c34931a1-d732-4c96-967c-2f2de4f63ce6", "type": "concept", "title": "Stakeholders, personas, process maps, pain points, jobs to be done, and future-state design"}, {"id": "ce22baed-bb36-4f61-a1ef-7d08b4123a9a", "type": "concept", "title": "Functional, data, integration, security, privacy, accessibility, performance, support, and compliance requirements"}, {"id": "13ffcca3-6379-4271-a4b2-c0aeb6dc04ca", "type": "concept", "title": "Request for information, market scan, references, demonstrations, sandbox trials, and proof of concept"}], "description": "Students separate mandatory capabilities and constraints from attractive but low-value features."}, {"id": "4777d22e-9df3-4760-8143-894a0a02ede2", "type": "subtopic", "title": "Evaluation and business case", "children": [{"id": "24197aa9-f1c7-4443-ab77-ffe242d06ed4", "type": "concept", "title": "Weighted criteria, scripted demos, use cases, scoring anchors, fit-gap analysis, and bias controls"}, {"id": "35e6bd88-66c5-4ac2-bd67-90275db1ce92", "type": "concept", "title": "Acquisition, implementation, interfaces, hardware, training, support, upgrades, exit, and total cost"}, {"id": "ad2eb0d4-ad80-4628-b405-9abbfe7bebe3", "type": "concept", "title": "Benefits, baseline, sensitivity, risk-adjusted value, payback, governance, and benefits owner"}], "description": "This subtopic combines quantitative and qualitative evidence into a transparent recommendation."}, {"id": "ef5e9ebd-2a58-44c1-91b6-0fb2d9404639", "type": "subtopic", "title": "Contracts and vendor governance", "children": [{"id": "3fc43124-5205-4a8f-964e-900f99e2bb24", "type": "concept", "title": "Scope, deliverables, milestones, acceptance, fees, renewals, change control, and warranties"}, {"id": "0283d27b-3ace-4df1-bfe5-a0abf14f9b78", "type": "concept", "title": "Service levels, uptime, support, security, data processing, insurance, indemnity, audit, and breach notification"}, {"id": "10c3e2f8-fddd-4cd7-90a4-dbf8dc24d034", "type": "concept", "title": "Data portability, integration access, subcontractors, benchmarking, termination, transition assistance, and vendor lock-in"}], "description": "Students learn the commercial and operational terms that sustain performance after the sale."}]}, {"id": "ebd4e2d1-e96a-4833-8098-b15b86b78f41", "type": "topic", "title": "Implementation, Change Management, and Adoption", "description": "Even good technology fails when workflow, configuration, training, incentives, and support are misaligned. Students learn to plan implementation as an operating-model change.", "children": [{"id": "ea504436-812a-4c88-9fff-6cbeb7018e3b", "type": "subtopic", "title": "Implementation lifecycle", "children": [{"id": "c16a5ef1-a6b4-49c8-8560-ee9a7460dd20", "type": "concept", "title": "Charter, governance, scope, plan, budget, risks, issues, decisions, and change control"}, {"id": "57c81a5a-54d5-4590-9c72-485dba408458", "type": "concept", "title": "Configuration, interfaces, data migration, testing, training, cutover, rollback, and hypercare"}, {"id": "c845ab85-6c2a-4e51-b8fa-5e3389e552fc", "type": "concept", "title": "Waterfall, agile, pilot, phased, parallel, and big-bang approaches"}], "description": "Students organize discovery through stabilization using explicit gates, ownership, evidence, and risk controls."}, {"id": "554a1f24-7794-408e-b3e0-86cd51baa886", "type": "subtopic", "title": "Data migration, testing, and readiness", "children": [{"id": "d79886ef-e369-47c8-a0a2-391afd5944c3", "type": "concept", "title": "Extract, cleanse, map, transform, load, reconcile, archive, and retention"}, {"id": "71965695-a289-40ec-8b9f-4eb7dbed1af1", "type": "concept", "title": "Unit, integration, end-to-end, security, performance, accessibility, recovery, and user acceptance tests"}, {"id": "9613d592-0013-4e0c-9b8a-c7f92ec4b24c", "type": "concept", "title": "Go-live criteria, defect severity, rehearsals, contingency, readiness dashboard, and sign-off"}], "description": "This subtopic protects operations by proving data, workflows, controls, and support before launch."}, {"id": "bdfe742a-4206-45b6-99c2-2facbabd907a", "type": "subtopic", "title": "Change, learning, and benefits realization", "children": [{"id": "94a671e8-21ca-4a9e-a9aa-eb0257af712e", "type": "concept", "title": "Stakeholder impact, sponsors, champions, resistance, communications, feedback, and psychological safety"}, {"id": "c5db00e6-e5c6-41d3-977b-9d7caafe00c9", "type": "concept", "title": "Role-based learning, practice environment, job aids, coaching, proficiency, and support model"}, {"id": "b15a5a76-3b75-4714-8f34-fc383b62ec43", "type": "concept", "title": "Adoption measures, process compliance, benefit measures, post-implementation review, and continuous improvement"}], "description": "Students plan for behavior, capability, and ownership—not just system availability."}]}, {"id": "aba95729-c16d-4aa9-a6b4-0074a93b63df", "type": "topic", "title": "Innovation, Responsible Technology, and the Future of Hospitality", "description": "The final section helps students investigate emerging technology without hype. They learn to test strategic relevance, operational feasibility, stakeholder impacts, and ethical boundaries.", "children": [{"id": "506f984c-6ead-4dea-ba46-0378b742c5fc", "type": "subtopic", "title": "Technology sensing and scenario analysis", "children": [{"id": "30ba81a2-f7bf-470f-a919-7d5db06b68a5", "type": "concept", "title": "AI agents, robotics, biometrics, spatial computing, digital identity, autonomous operations, and new platforms"}, {"id": "456efb80-9624-4656-b201-e0a5d44ed9c3", "type": "concept", "title": "Horizon scanning, trend evidence, maturity, diffusion, dependencies, and uncertainty"}, {"id": "82dbb206-fad9-4563-9a6d-2002b0917ff9", "type": "concept", "title": "Scenarios, signposts, options, experiments, stop criteria, and portfolio balance"}], "description": "Students build a repeatable process for recognizing signals and examining plausible futures."}, {"id": "994de3c3-fa0d-4661-a16f-2ec6f5a65a4c", "type": "subtopic", "title": "Responsible innovation", "children": [{"id": "615aaa9c-0928-4cec-bc40-7eda893c0930", "type": "concept", "title": "Guest and employee participation, accessibility, labor impacts, deskilling, and power"}, {"id": "44c42878-560b-4901-ba96-1d9673ee2e44", "type": "concept", "title": "Privacy, bias, security, safety, explainability, contestability, and human oversight"}, {"id": "bca3a2d3-b35d-4b0b-8a8b-3a09e8a41d5a", "type": "concept", "title": "Responsible AI governance, impact assessment, red teams, monitoring, appeals, and retirement"}], "description": "This subtopic makes values, affected groups, and potential harms part of the design decision."}, {"id": "b55946c6-a839-4cde-bc95-0fcf93af1a36", "type": "subtopic", "title": "Sustainability and shared value", "children": [{"id": "dc8d69b2-1e5b-4bbe-9de1-7ab28b122da6", "type": "concept", "title": "Energy, water, waste, carbon, travel, procurement, and behavior-change applications"}, {"id": "8c5cba5c-471c-4aff-add7-0c6a277882c8", "type": "concept", "title": "Hardware life cycle, e-waste, cloud and AI energy use, repairability, and supplier practices"}, {"id": "2d9d15da-2589-485b-bc4e-ea6715b8060c", "type": "concept", "title": "Baseline, materiality, rebound effects, green claims, assurance, stakeholder value, and transparent reporting"}], "description": "Students evaluate whether technology improves environmental and social outcomes across its full life cycle."}]}], "dbBacked": true}$hisyjson$::jsonb,
